-- Seed: Requisiti
INSERT INTO requisiti (codice,versione,categoria,sottocategoria,titolo,descrizione,contesto,note,importanza,std,owner,appl_dc_ingegneria,appl_dc_change,appl_dc_run,appl_sviluppo) VALUES
  ('SEC-AM2-001.00','2','Asset Management (ID.AM)','ID.AM-2: Sono censite le piattaforme e le applicazioni software in uso nell''''organizzazione','Censimento Application Portfolio  / Asset Inventory','Tutti gli elementi ed i componenti finalizzati all''''erogazione di un servizio o al funzionamento di una applicazione devono essere censiti opportunamente.','','','MUST','LGA','DC - Change','','si','','si'),
  ('SEC-AM2-001.01','1','Asset Management (ID.AM)','ID.AM-2: Sono censite le piattaforme e le applicazioni software in uso nell''''organizzazione','Censimento Application Portfolio / Asset Inventory di componenti applicative','Sono necessarie le seguenti attività di censimento su Application Portfolio:\\\\\\\\n- componenti software che implementano l''''applicazione\\\\\\\\n- librerie di terze parti relative al software stesso\\\\\\\\n- tipo di database e tipologia informazioni che sono memorizzate','','Guida Application Portfolio\\\\\\\\n\\\\\\\\nrif. Application Portfolio: Emanule Mellini, Ilaria Borgnoli\\\\\\\\n\\\\\\\\nrif. CMDB/CI Inventory: Carmelo Scafidi','MUST','LGA','','','','','si'),
  ('SEC-AM2-001.02','1','Asset Management (ID.AM)','ID.AM-2: Sono censite le piattaforme e le applicazioni software in uso nell''''organizzazione','Censimento Application Portfolio / Asset Inventory di componenti di sistema','Sono necessarie le seguenti attività di censimento:\\\\\\\\n\\\\\\\\n- sistemi su cui verranno installate le componenti applicative\\\\\\\\n- reti su cui verranno attestati i sistemi di cui al punto precedente\\\\\\\\n- quali repository e quali indici saranno adottati per i log','','Guida Application Portfolio\\\\\\\\n\\\\\\\\nrif. Application Portfolio: Emanule Mellini, Ilaria Borgnoli\\\\\\\\n\\\\\\\\nrif. CMDB/CI Inventory: Carmelo Scafidi','MUST','','DC - Change, DC - RUN','','si','si',''),
  ('SEC-AM8-001.00','1','Asset Management (ID.AM)','DP-ID.AM-8: I trattamenti di dati personali sono identificati e catalogati','Censimento e tipologia di informazioni','E'''' necessario identificare all''''interno dell''''iniziativa sia la tipologia di dati trattati che l''''ambito circoscritto di interesse e/o eventuali controlli di sicurezza già in essere.','','','MUST','RIF-108
LGA','','si','','','si'),
  ('SEC-RA1-001.00','2','Risk Assessment (ID.RA)','ID.RA-1: Le vulnerabilità delle risorse (es. sistemi, locali, dispositivi) dell''''organizzazione sono identificate e documentate','Test di sicurezza','I test di sicurezza (Vulnerability Assessment e Penetration Test) devono essere condotti sia sul sistema oggetto di realizzazione nella sua interezza, sia sulle singole parti che lo compongono (es. applicazioni, sistemi, apparati, ...)\\\\\\\\n\\\\\\\\nÈ necessario che l''''esito dei test di sicurezza non evidenzi vulnerabilità o rischi, o che queste siano risolte prima del passaggio in produzione.','','Per l''''esecuzione dei test è necessario aprire un task Sicurezza Applicativa (SA) - Security Test','MUST','LGA','','','','','si'),
  ('SEC-RA1-002.00','2','Risk Assessment (ID.RA)','ID.RA-1: Le vulnerabilità delle risorse (es. sistemi, locali, dispositivi) dell''''organizzazione sono identificate e documentate','Manutenibilità software e sistemi','Tutti i sistemi e i software adottati internamente ad Azienda, inclusi quelli acquisiti dall''''esterno, devono:\\\\\\\\n\\\\\\\\n - essere tecnologicamente aggiornati (es. utilizzare metodi di cifratura non obsoleti)\\\\\\\\n - garantire il rispetto delle best practice di sicurezza correnti (es. essere in grado di integrarsi con strumenti di autenticazione centralizzati)\\\\\\\\n - essere soggetti a evoluzione e manutenzione regolare, con particolare attenzione all''''emissione delle patch di sicurezza, da parte del vendor o della community di riferimento.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-RA4-001.00','1','Risk Assessment (ID.RA)','ID.RA-4: Sono identificati i potenziali impatti sul business e le relative probabilità di accadimento','Criticità Asset e Servizi','Per l''''identificazione dei corretti scenari di analisi e mitigazione, è necessario riportare a sicurezza la criticità di quanto in analisi indicando:\\\\\\\\n\\\\\\\\nSPONSOR: BIA (se già fatta) o in alternativa identificare impatti e criticità del servizio dal punto di vista Business. Possibilmente indicare se in possesso anche RTO e RPO attesi.\\\\\\\\nDC: Su servizi già esistenti, identificazione degli elementi di infrastruttura impattati e relativo grado di criticità degli stessi\\\\\\\\nSVILUPPO: Identificazioni di eventuali elementi software richiamati o riutilizzati o impattati dall''''iniziativa','','','MUST','','','','','',''),
  ('SEC-RA4-002.00','1','Risk Assessment (ID.RA)','ID.RA-4: Sono identificati i potenziali impatti sul business e le relative probabilità di accadimento','BCDR - Parametri','Il servizio deve essere predisposto per rispettare i vincoli di RPO e RTO definiti dalla BIA o imposti come SLA contrattuale.','','','MUST','RIF-101','','si','','',''),
  ('SEC-RA4-003.00','1','Risk Assessment (ID.RA)','ID.RA-4: Sono identificati i potenziali impatti sul business e le relative probabilità di accadimento','BCDR - Fornitori critici','I contratti di fornitura di servizi esterni devono contenere precise clausole per assicurare la disponibilità necessaria ad attuare il piano di ripristino.','','','MUST','RIF-109
LGA','','si','','','si'),
  ('SEC-AC1-001.00','3','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Account','Account personali\\\\\\\\n\\\\\\\\nTutti gli account che permettono accesso interattivo ad applicazioni o sistemi devono essere nominali e non cedibili, al fine di garantire l''''accountability delle azioni eseguite. Le credenziali devono quindi essere note solo al titolare dell''''account, non condivise con terzi, e conservate con cura in sistemi che ne garantiscano la confidenzialità (ad esempio password manager locali come KeePass, invece della corrispondente funzionalità dei browser).\\\\\\\\n\\\\\\\\nAccount tecnici\\\\\\\\n\\\\\\\\nGli account tecnici, ovvero quelli destinati all''''uso da parte di servizi o applicazioni:\\\\\\\\n\\\\\\\\n - devono essere destinati all''''uso da parte di un solo servizio o applicazione e non devono essere condivisi tra servizi o applicazioni distinte\\\\\\\\n\\\\\\\\n - devono avere i privilegi minimi necessari per il corretto funzionamento dell''''applicazione o servizio associato e non devono avere nessun privilegio ulteriore\\\\\\\\n\\\\\\\\n - non devono permettere l''''accesso interattivo\\\\\\\\n\\\\\\\\n - devono essere correttamente censiti e documentati\\\\\\\\n\\\\\\\\nGestione eccezioni\\\\\\\\n\\\\\\\\nTutte le eccezioni devono essere opportunamente documentate ed approvate.\\\\\\\\n\\\\\\\\nGli account non nominali e con accesso interattivo (account condivisi) che non possono essere disabilitati devono essere gestiti in modo da garantirne l''''accountability, ad esempio per il tramite di macchine ponte, registrando le sessioni d''''uso o tramite opportune procedure operative (vedi Procedura Operativa per la Gestione delle Utenze di Emergenza).','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC1-001.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Processi di gestione degli account','Devono essere definiti e documentati i processi di creazione, modifica, abilitazione, disabilitazione e cancellazione degli account ed i criteri di approvazione o di diniego delle operazioni di gestione degli account stessi','','Integrazione con i processi IAM','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC1-001.02','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Centralizzazione dell''''autenticazione','L''''autenticazione delle utenze (personali e tecniche) che accedono ad applicazioni e sistemi di Azienda deve avvenire tramite sistemi centralizzati.\\\\\\\\n\\\\\\\\nIn particolare:\\\\\\\\n\\\\\\\\n - per sistemi ed applicazioni ad uso interno, l''''autenticazione degli utenti deve avvenite tramite integrazione con i sistemi centralizzati governati da IAG, ovvero:\\\\\\\\n    + tramite integrazione con Keycloack per le applicazioni web\\\\\\\\n    + tramite integrazione diretta con Active Directory per sistemi, DB o applicazioni che implementano Kerberos\\\\\\\\n  - per applicazioni ad uso clienti, l''''autenticazione degli utenti deve avvenite tramite integrazione con i realm Keycloack dedicati ai clienti (es. CIAM Identity Core)\\\\\\\\n\\\\\\\\nAllo scopo di garantire resilienza in caso di incidenti, e per fini di amministrazione di sistemi ed applicazioni, possono essere definite alcune utenze locali, le cui caratteristiche, autorizzazioni e processi di utilizzo devono essere definite e concordate con l''''ufficio IAM. Si veda anche il requisito SEC-AC1-002.00.','','','MUST','','','','','',''),
  ('SEC-AC1-002.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Account di default','Gli account di default con privilegi amministrativi (e.g. root, administrator, etc.) devono essere resi inutilizzabili.\\\\\\\\nSe non è possibile disabilitarli, è necessario seguire l''''apposita procedura per la gestione delle utenze di emergenza.','','Procedura Operativa per la Gestione delle Utenze "Dual Control Just in Time"','MUST','Change','','','si','',''),
  ('SEC-AC1-003.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Certificati digitali','Se non altrimenti necessario, i certificati digitali, per qualunque scopo utilizzati, devono essere erogati dalle CA di Azienda. Il ricorso ad altre CA deve essere esplicitamente approvato.\\\\\\\\nL''''uso di certificati digitali autofirmati o di certificati che includono wildcard è vietato.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC1-003.01','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Gestione certificati','L''''utilizzo dei certificati digitali deve prevedere:\\\\\\\\n - Il monitoraggio centralizzato delle scadenze dei certificati\\\\\\\\n - Un sistema di rinnovo automatizzato che preveda il rinnovo dei certificati con un congruo anticipo rispetto alla loro scadenza\\\\\\\\n - in caso di rinnovo, il nuovo certificato deve avere inizio validità antecedente rispetto alla scadenza di quello precedente\\\\\\\\n - In caso di terminatori crittografici ridondati, l''''adozione di certificati diversi per ogni nodo con scadenze differenti, in modo da evitare che scadano tutti nello stesso momento. (Esempio: nel caso di terminatore TLS ridondato per lo stesso sito i due nodi del terminatore avranno due certificati con durata annuale e scadenza con 6 mesi di differenza)','','Fare riferimento allo standard DC 21 - STANDARD - Certificati (Gestione Automatizzata) - documentazione interna durata dei certificati TLS pubblici è destinata a diminuire nel tempo e richiede quindi interventi di automazione per la loro gestione; vedasi https://cabforum.org/2025/04/11/ballot-sc081v3-introduce-schedule-of-reducing-validity-and-data-reuse-periods/','MUST','LGA','','','','','si'),
  ('SEC-AC1-003.02','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Chiavi private dei certificati ','Le chiavi private legate a certificati usati per la cifratura, l''''autenticazione o la firma:\\\\\\\\n\\\\\\\\n - non devono essere utilizzate da più sistemi o applicazioni\\\\\\\\n - non devono essere esportate dai keystore (HSM per gli utilizzi più critici o key store software opportunamente protetti) in cui sono state generate, se non a scopo di backup e con le necessarie precauzioni finalizzate a mantenere segreta la chiave stessa (e.g. utilizzo di chiavi di wrap cioè proteggendo con cifratura la chiave stessa mediante ulteriore apposita chiave).\\\\\\\\nNota: ad esempio, la generazione della coppia di chiavi utilizzata per generare la richiesta di certificato deve essere effettuata in ambiente protetto e possibilmente già all''''interno del key store dove verrà utilizzata, evitando trasferimenti, la configurazione "non esportabile" è da preferire dove possibile.','','','MUST','LGA','','','','','si'),
  ('SEC-AC1-004.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-1: Le identità digitali e le credenziali di accesso per gli utenti, i dispositivi e i processi autorizzati sono amministrate, verificate, revocate e sottoposte a audit sicurezza','Vaulting','Tutte le credenziali, le chiavi di autenticazione e di cifratura e tutte le quantità segrete devono essere gestite tramite appositi sistemi di vaulting che ne evitino l''''esposizione non necessaria.','','Vault - Reparto Sicurezza - Confluence','MUST','LGA','','','','','si'),
  ('SEC-AC3-001.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-3: L''''accesso remoto alle risorse è amministrato','Accesso remoto e VPN','L''''accesso delle postazioni di lavoro alle reti interne deve avvenire tramite l''''uso di una VPN client-to-site ed una autenticazione a 2 fattori.','','','MUST','LGA','','','','','si'),
  ('SEC-AC3-002.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-3: L''''accesso remoto alle risorse è amministrato','ACL per accesso amministrativo dei clienti','Le funzionalità amministrative accedute dai clienti per la configurazione dei propri servizi devono essere protette con una ACL dinamica che, in seguito ad una corretta autenticazione, abiliti esclusivamente l''''indirizzo IP del cliente e gli eventuali ulteriori indirizzi IP esplicitamente autorizzati dal cliente medesimo.','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC3-003.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-3: L''''accesso remoto alle risorse è amministrato','Transito da macchina ponte','Tutti gli accessi, sia amministrativi che non amministrativi, a sistemi, DB e applicazioni in ambiente di produzione devono avvenire esclusivamente tramite accesso a macchina ponte.\\\\\\\\n\\\\\\\\nPossono fare eccezione gli accessi verso interfacce web che presentano funzionalità o implementano una profilazione degli utenti tale da non permettere l''''accesso a:\\\\\\\\n\\\\\\\\n - applicazioni che implementano funzionalità amministrative (creazione e gestione utenze, avvio delle applicazioni stesse, etc.)\\\\\\\\n - console che aggregano e analizzano i log di sicurezza\\\\\\\\n - impostazioni di sicurezza di altri sistemi o applicazioni\\\\\\\\n - keystore e password vault\\\\\\\\n - sistemi o applicazioni di monitoraggio\\\\\\\\n - applicazioni di particolare criticità','','','MUST','','','','','',''),
  ('SEC-AC4-001.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Gestione autorizzazioni per ruoli (RBAC)','I diritti di accesso devono essere assegnati per ruolo. I ruoli rappresentano un insieme di autorizzazioni che possono essere assegnate agli utenti. Gli utenti possono avere uno o più ruoli, e ogni ruolo può avere un insieme di autorizzazioni diverso.\\\\\\\\n\\\\\\\\nDeve essere documentata una matrice (RBAC) che mette in correlazione autorizzazioni e ruoli.\\\\\\\\n\\\\\\\\nLa naming convention da adottare e le linee guida da seguire per la gestione dei ruoli e matrice RBAC sono riportati in dettaglio alla seguente pagina: RBAC\\\\\\\\n\\\\\\\\nDeve essere ingaggiato l''''ufficio IAM (DES - Supporto Progetti - IAM) per la definizione della matrice RBAC, la validazione delle attribuzioni delle autorizzazioni e per le richieste di associazione ruolo → gruppo ← utenti','','Task SEC su Jira con componente "DES - Supporto progetti - IAM"','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC4-001.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Funzioni privilegiate','L''''accesso a funzionalità privilegiate deve essere limitato alle sole necessità previste dal ruolo assegnato all''''utente.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC4-002.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Dual control','Le operazioni che presentano un livello di rischio particolarmente elevato devono essere configurate in modo da richiedere la presenza di almeno due persone (dual control / four eyes).\\\\\\\\nQuesto è necessario ad esempio per:\\\\\\\\n - operazioni di gestione di chiavi su HSM o vault (e.g. modifica, generazione etc.)\\\\\\\\n - accesso con account amministrativi non nominali su componenti infrastrutturali','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC4-003.00','4','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Accesso ai dati','In caso di conservazione di dati riservati (dati personali, dati di business, dati di configurazione, dati di sicurezza quali i log) è necessario prevedere dei meccanismi atti a limitare l''''accesso ai soli dati strettamente necessari da parte degli utenti autorizzati. ','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC4-003.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Accesso sistemistico ai dati','Gli utenti che dispongono di privilegi amministrativi (sistemisti, DBA, etc.) ma che non hanno esplicita necessità di accedere ai dati devono avere un profilo di accesso che impedisca l''''accesso ai dati medesimi; a tal fine può essere necessario prevedere la cifratura dei dati a livello di file, DB o singolo dato.','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC4-003.02','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Accesso applicativo ai dati','I ruoli applicativi che necessitano di accedere ai dati o di eseguire ricerche devono utilizzare interfacce / tool di inquiry in grado di garantire che i dati acceduti non eccedano la stretta necessità; a tal fine sono da adottare le seguenti misure associate ai profili di accesso:\\\\\\\\n\\\\\\\\n - Mascheramento dei dati: nascondere alcune porzioni dei dati riservati, consentendo agli utenti di visualizzare solo una parte limitata delle informazioni (es. mar****si@gmail.com).\\\\\\\\n - Nessuna visualizzazione di default: al caricamento della pagina dei form di ricerca non deve essere mostrato nessun dato\\\\\\\\n - Possibilità di ricerche puntuali: il sistema deve consentire le ricerche solamente compilando i campi con dati identificativi e univoci quali ad esempio: la coppia nome e cognome, l''''ID cliente;, l''''indirizzo email, il numero di telefono.\\\\\\\\n - Limitazione dei risultati della ricerca: deve essere impostato un limite sul numero di risultati restituiti da una singola ricerca per evitare l''''accesso ai dati eccessivo (es. mostrare solo i primi 25 record); a tal fine può essere necessario consentire agli utenti di applicare filtri specifici durante la ricerca per restringere i risultati ai dati maggiormente pertinenti.\\\\\\\\n - Limitazione dei campi risultanti da una ricerca: le pagine che presentano l''''elenco dei risultati della ricerca devono visualizzare solo il set di dati necessari a identificare univocamente ciascun record senza presentare tutti i campi (es. non visualuzzare email, telefono o indirizzo di casa nella scheramata dei risultati della ricerca).\\\\\\\\n - Crittografia dei dati: crittografare i dati riservati nella base dati in modo che la decifratura sia possibile solo per specifici profili autorizzati.\\\\\\\\n - Protezione dei campi sensibili: limitare ai soli utenti autorizzati l''''accesso ai campi che contengono dati riservati (es. alcuni campi di dati possono essere visualizzati solo dai profili che dispongono di apposito privilegio)','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC4-003.03','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Download massivo di dati','Il download massivo di dati deve essere controllato nel seguente modo:\\\\\\\\n\\\\\\\\n - devono essere pre-definiti i soggetti (e le rispettive utenze) che hanno possibilità di scaricare i dati\\\\\\\\n - i download devono avere informazioni minime (ossia solamente quelle strettamente necessarie) e pre-definite\\\\\\\\n - salvo casi motivati, individuati ed opportunamente gestiti non deve essere possibile effettuare lo scarico dell''''intera banca dati, definendo un numero massimo di dati scaricabili (ad es. 250 righe per tabella)\\\\\\\\n\\\\\\\\nTutti gli eventi di download massivo devono generare log come specificato in SEC-CM1-001.03.','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC4-004.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Privilegi applicativi','Il livello di privilegio associato alle componenti applicative e di sistema deve essere il più basso possibile. \\\\\\\\nAd esempio, le applicazioni devono girare con utenza tecnica dedicata, con privilegi opportuni, e non con utenza amministrativa.\\\\\\\\nIl livello di privilegio associato alle componenti applicative non deve essere superiore al livello di privilegio accordato agli utenti che accedono a tali componenti applicative.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC4-005.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Impersonation e assistenza','Al fine di permettere all''''operatore di assistenza clienti di agire in vece del cliente vanno rispettati i seguenti limiti:\\\\\\\\n\\\\\\\\n - Vanno definite le condizioni sotto cui l’operatore può impersonare l’utente: su richiesta dello stesso, per situazioni di emergenza definite ed esplicitate agli utenti stessi, etc. Tali condizioni devono essere esplicitate e tracciate prima di eseguire l''''operazione.\\\\\\\\n - l''''utente che richiede l''''intervento deve essere riconosciuto (autenticato) con livello di confidenza coerente con la criticità delle operazioni richieste. (es. se l''''accesso utente è soggetto ad autenticazione a due fattori, non si può accettare una richiesta tramite ticket inserito con autenticazione semplice)\\\\\\\\n - Deve essere sempre garantita l’accountability delle operazioni eseguite, mediante tracciatura:\\\\\\\\n    + Degli accessi mediante utenze nominali\\\\\\\\n    + Delle singole operazioni svolte dagli operatori\\\\\\\\n - Al cliente deve essere notificato l''''accesso e le operazioni svolte in sua vece\\\\\\\\n - Il cliente deve poter verificare l’operato eseguito in sua vece; le trace visibili dal cliente non devono contenere riferimento all''''identità personale dell''''operatore (no a utenze composta da nome e cognome; sì a id come operatore)\\\\\\\\n - il cliente deve poter disconoscere le operazioni eseguite dall''''operatore (es. con una funzione simile a quanto previsto per gli accessi utente ma con la possibilità di dichiarare le operazioni eseguite dall''''operatore con congruenti con quanto richiesto)\\\\\\\\n - Nei casi in cui la procedura è attivata per attività richieste da autorità e forze dell''''ordine, la notifica e la tracciatura dell''''attività non devono essere visibili all''''utente. Per questa casistiche la notifica di accesso deve essere inviata al richiedente interno e a sicurezza\\\\\\\\n - La sussistenza e la congruenza delle condizioni a giustificazione delle operazioni svolte nelle veci del cliente devono essere verificate da un supervisore\\\\\\\\n - La disponibilità della funzione di impersonificazione deve essere limitata al solo personale indispensabile e per il tempo strettamente necessario','','','MUST','LGA','','','','','si'),
  ('SEC-AC4-006.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Diritti di accesso alle impostazioni di logging','L''''accesso alle impostazioni di logging deve essere limitato esclusivamente agli utenti con privilegi di amministrazione dei sistemi, apparati e applicazioni.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-AC4-007.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Diritti di accesso ai log','L''''accesso al contenuto dei log deve essere limitato esclusivamente agli utenti all''''uopo autorizzati.','','','MUST','','','','','',''),
  ('SEC-AC4-007.01','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-4: I diritti di accesso alle risorse e le relative autorizzazioni sono amministrati secondo il principio del privilegio minimo e della separazione delle funzioni','Protezione dei backup dei log','Le copie di backup dei log devono essere sottoposte alle medesime misure di protezione dei log stessi.','','','MUST','','','','','',''),
  ('SEC-AC5-001.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Segregazione di rete','Applicazioni che erogano funzionalità ad uso interno devono essere installate in segmenti di rete opportunamente segregati e raggiungibili unicamente dalle postazioni di lavoro Azienda o da controparti esterne autorizzate.','','Per "segregazione" si intende che una applicazione o sistema:\\\\\\\\n\\\\\\\\n - non sia raggiungibile da traffico di rete a livello 3, essendo questo opportunamente bloccato da regole di firewalling\\\\\\\\n - non sia raggiungibile da traffico ICMP\\\\\\\\n - la risoluzione del nome di dominio in un indirizzo IP non sia disponibile','MUST','RIF-103','','si','','',''),
  ('SEC-AC5-002.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Architettura di rete a livelli','L''''architettura di rete deve essere organizzata in almeno tre livelli:\\\\\\\\n - livello di front-end che contiene l''''interfaccia utente e rappresenta il punto di ingresso dell''''applicazione\\\\\\\\n - livello di back-end, che contiene la logica per la gestione delle richieste\\\\\\\\n - livello database per la memorizzazione dei dati.\\\\\\\\nOgni livello deve essere separato fisicamente o logicamente dagli altri per evitare l''''accesso non autorizzato tra di essi.','','Rif. 02 - Criteri di utilizzo delle Reti - Data Center - Confluence (intranet.example)','MUST','RIF-103
LGA','','si','','','si'),
  ('SEC-AC5-003.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Segregazione degli ambienti elaborativi','L''''architettura di rete deve essere organizzata in modo da suddividere i sistemi in base alla finalità d''''uso, alla presenza di dati e alle necessità di accesso.\\\\\\\\nDevono essere previsti almeno gli ambienti di: Sviluppo, Test, Demo, Produzione (che comprende il DR).\\\\\\\\nAltri ambienti devono essere previsti in base a necessità specifiche, anche temporanee (es. se risulta necessario effettuare test di non regression con dati reali è necessario prevedere ambienti dedicati in area di produzione/demo o con protezioni equivalenti).\\\\\\\\nAltri ambienti dedicati devono essere previsti per servizi di particolare criticità (es. i sistemi che effettuano attività di aggregazione e centralizzazione dei dati, e che per questo scopo estraggono dati da altre basi dati aziendali, devono essere posizionati in segmenti di rete dedicati e protetti, con regole di firewalling che limitino l''''accesso ai soli sistemi autorizzati).','','Rif. Standard security architecture - Networking - Dati-VS-Ambienti','MUST','','','','','',''),
  ('SEC-AC5-003.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Segregazione degli ambienti ausiliari','L''''architettura di rete deve essere organizzata in modo da separare gli ambienti ausiliari rispetto agli altri ambienti elaborativi e rispetto alla rete pubblica.\\\\\\\\n\\\\\\\\nDevono essere previsti almeno gli ambienti di: rete di gestione, Office, sicurezza fisica.','','','MUST','','','','','',''),
  ('SEC-AC5-004.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Isolamento delle reti','Devono essere implementati dei meccanismi di isolamento delle reti come VLAN (Virtual Local Area Network) o sottoreti per separare i diversi ambienti e i diversi livelli della rete.\\\\\\\\n\\\\\\\\nDevono essere assegnate una VLAN/sottorete specifica al livello front-end (o DMZ), una diversa al livello back-end e una terza al livello database.','','','MUST','','','','','',''),
  ('SEC-AC5-005.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Utilizzo di firewall','La segregazione di rete deve essere ottenuta tramite firewall, che comprendono firewall tradizionali di rete (gateway), firewall locali e sistemi di microsegmentazione.\\\\\\\\n\\\\\\\\nI firewall devono essere configurati per filtrare il traffico di rete tra i diversi ambienti e livelli e devono essere definite delle politiche di sicurezza per consentire solo le comunicazioni necessarie tra le diverse componenti (e.g. consentire solo il traffico HTTP/HTTPS tra il livello front-end ed il livello back-end e limitare l''''accesso al livello database soltanto dal livello back-end).\\\\\\\\n\\\\\\\\nIn ogni caso il traffico da e per reti non-trusted (e.g. rete pubblica) è ammesso esclusivamente con il livello front-end (DMZ).','','','MUST','RIF-103
LGA','','si','','','si'),
  ('SEC-AC5-005.01','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Configurazione dei firewall','I firewall devono essere configurati in modo da:\\\\\\\\n\\\\\\\\n - bloccare tutto il traffico che non è esplicitamente autorizzato\\\\\\\\n - consentire solo comunicazioni punto-punto esplicitamente definite, evitando aperture da o verso un insieme indefinito di indirizzi (any) o porte quando non vi sono motivazioni legate all''''erogazione del servizio (es. interfacce applicative esposte al pubblico)\\\\\\\\n - impedire le connessioni che utilizzano protocolli insicuri (e.g. protocolli che trasmettono informazioni in chiaro, in particolare le password).\\\\\\\\n - assicurare la segregazione delle reti orizzontalmente (segregazione degli ambienti di elaborazione) e verticalmente (definizione dei livelli di elaborazione)\\\\\\\\n - limitare fortemente l''''uso di protocolli classificati da Threat Intelligence come particolarmente rischiosi (e.g. nel 2023 RPC, SMB, SSH, LDAP, ICMP, DNS, ARP, RDP)','','','MUST','','','','','',''),
  ('SEC-AC5-005.02','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','IDS','Il traffico che transita attraverso i firewall perimetrali deve essere sottoposto anche a controlli per la rilevazione delle intrusioni.\\\\\\\\nNon è richiesto per i firewall interni.','','','MUST','','','','','',''),
  ('SEC-AC5-006.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Rete di gestione','La rete di gestione deve ospitare tutti i sistemi che hanno lo scopo di:\\\\\\\\n\\\\\\\\n - mantenere e gestire le configurazioni degli apparati di rete\\\\\\\\n - mantenere e gestire le configurazioni dei sistemi\\\\\\\\n - connettersi alle porte di management dei sistemi fisici','','','MUST','','','','','',''),
  ('SEC-AC5-006.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Accesso limitato alla rete di gestione','L''''accesso alla rete di gestione:\\\\\\\\n\\\\\\\\n - deve essere limitato al personale autorizzato con privilegi elevati\\\\\\\\n - deve utilizzare meccanismi di autenticazione forte, con l''''autenticazione a due fattori\\\\\\\\n - deve prevedere l''''assegnazione di livelli appropriati di autorizzazione in base ai ruoli e alle responsabilità del personale.','','','MUST','','','','','',''),
  ('SEC-AC5-006.02','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Isolamento della rete di gestione','La rete di gestione deve essere isolata fisicamente o virtualmente dal resto della rete aziendale. Ciò deve essere fatto tramite:\\\\\\\\n\\\\\\\\n - uso di firewall per la segregazione\\\\\\\\n - reti fisiche o VLAN separate\\\\\\\\n - uso di VDI o macchine ponte in modo da disintermediare i sistemi di gestione dalle postazioni di lavoro.','','','MUST','','','','','',''),
  ('SEC-AC5-006.03','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Monitoraggio costante della rete di gestione','Devono essere implementati sistemi di monitoraggio e rilevamento delle intrusioni sulla rete di gestione per identificare eventuali attività sospette o tentativi di accesso non autorizzati.\\\\\\\\n\\\\\\\\nDevono essere utilizzati strumenti di registrazione e logging degli eventi per tracciare le attività di gestione e identificare,  anche a posteriori, eventuali violazioni (e.g trace e/o session recording).','','','MUST','','','','','',''),
  ('SEC-AC5-006.04','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Accesso remoto sicuro alla rete di gestione','Per l''''accesso remoto devono essere utilizzare connessioni crittografate VPN (Virtual Private Network) con 2FA. Per maggior resilienza deve essere assicurato un canale di accesso alternativo:\\\\\\\\n\\\\\\\\n - fisico dai datacenter\\\\\\\\n - logico con una seconda VPN con asimmetria tecnologica rispetto alla principale.','','','MUST','','','','','',''),
  ('SEC-AC5-006.05','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Patching e aggiornamenti regolari','I dispositivi e i sistemi di gestione devono essere mantenuti aggiornati con le ultime patch di sicurezza e gli aggiornamenti del firmware.\\\\\\\\n\\\\\\\\nDevono essere effettuati regolari controlli di sicurezza e di verifica della conformità dei dispositivi di gestione.','','','MUST','Change','','','si','',''),
  ('SEC-AC5-006.06','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Segmentazione logica della rete di gestione','La rete di gestione deve essere suddivisa in segmenti logici o zone, in base ai requisiti di sicurezza e alle funzionalità dei sistemi in modo da limitare l''''accesso solo alle risorse e ai sistemi necessari per le attività di gestione specifiche.','','','MUST','','','','','',''),
  ('SEC-AC5-006.07','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-5: L''''integrità di rete è protetta (es. segregazione di rete, segmentazione di rete)','Backup e ripristino della rete di gestione','Devono essere implementate delle procedure di backup regolari dei dispositivi di gestione e dei dati critici.\\\\\\\\n\\\\\\\\nLa correttezza dei backup deve essere verificata e i processi di ripristino per garantire la disponibilità dei dati in caso di perdita o danneggiamento devono essere periodicamente sperimentati.','','','MUST','','','','','',''),
  ('SEC-AC6-001.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-6: Le identità sono comprovate, associate a credenziali e verificate durante le interazioni','Validazione dei token di autenticazione tramite indirizzo IP','Nel caso sia prevista l''''autenticazione da parte di un identity provider che rilascia un token (applicativo, OpenID, altro) è necessario, in fase di validazione del token ed autorizzazione all''''accesso, che l''''IP di provenienza della richiesta sia il medesimo per il quale il token è stato emesso, al fine di limitare furti di identità o di sessioni.','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC7-001.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Composizione e gestione Password','Al fine di avere password robuste e non facilmente "indovinabili", le password devono rispettare i seguenti vincoli:\\\\\\\\n\\\\\\\\nCon RBA:\\\\\\\\nLunghezza password minima consentita N caratteri 10\\\\\\\\nScadenza max = 12 mesi\\\\\\\\n\\\\\\\\nCon 2FA:\\\\\\\\nLunghezza password minima consentita N caratteri 8\\\\\\\\nScadenza max = infinito (salvo reset a fronte di: password compromessa o accessi sospetti)\\\\\\\\n\\\\\\\\nIn altri casi:\\\\\\\\nScadenza max = 6 mesi\\\\\\\\nLunghezza password minima consentita N caratteri - N =14\\\\\\\\n\\\\\\\\nIn tutti i casi:\\\\\\\\nLunghezza password massima consentita N caratteri  N= 64\\\\\\\\nLa password deve contenere almeno un carattere minuscolo\\\\\\\\nLa password deve contenere almeno un carattere maiuscolo\\\\\\\\nLa password deve contenere almeno un carattere speciale tra  !"#$%&''''()*+,-./:;<=>?@[\\\\]^_`{|}~\\\\\\\\nLa password deve contenere almeno un numero\\\\\\\\nLa password può contenere il carattere spazio " "\\\\\\\\nLa password non deve contenere il carattere spazio come primo o ultimo carattere\\\\\\\\nLa password non deve contenere più di 3 caratteri uguali ripetuti in successione\\\\\\\\nLa password non deve essere compresa in elenchi di password deboli o in dizionari di password note (gestite in una blacklist)\\\\\\\\nLa password non deve contenere lo username\\\\\\\\nLa password deve essere diversa dalle ultime 3','','La scadenza della password deve essere determinata esclusivamente dai meccanismi di gestione della password stessa, come l''''impostazione iniziale, il cambio o il reset. L''''abilitazione della 2FA non deve in alcun modo alterare questa informazioni, ma deve limitarsi a sospendere il controllo sulla validità temporale della password.\\\\\\\\n\\\\\\\\nNel caso in cui la 2FA venga disabilitata dopo la scadenza della password, il controllo sulla validità temporale deve essere immediatamente ripristinato, costringendo l''''utente a rinnovare la password al successivo accesso se questa risulta scaduta. Deve inoltre essere inviata o mostrata una notifica che invita l''''utente ad aggiornare la password se questa risulta scaduta alla disattivazione della 2FA.','MUST','LGA','','','','','si'),
  ('SEC-AC7-002.00','4','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Conservazione password','Le password degli utenti non devono mai essere salvate in chiaro. E'''' necessario conservarle proteggendole tramite un algoritmo di cifratura monodirezionale, da cui non sia possibile recuperare la password in chiaro.\\\\\\\\n','','','MUST','LGA','','','','','si'),
  ('SEC-AC7-002.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Algoritmi di protezione delle password approvati','L''''algoritmo utilizzato per la conservazione delle password deve essere conforme con quanto previsto nella tabella:\\\\\\\\n\\\\\\\\ndocumentazione interna','','https://www.gpdp.it/temi/cybersecurity/password/conservazione-delle-password','MUST','LGA','','','','','si'),
  ('SEC-AC7-002.02','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Gestione della conservazione delle password','Salvo esigenze specifiche, la conservazione delle password deve essere concentrata su sistemi di identity provider centralizzati (CIAM, Active Directory, etc.) evitando di creare nuovi archivi e/o utenze locali.\\\\\\\\n\\\\\\\\nLe password devono essere cancellate (anche se sotto forma di hash) quando non sono più necessarie per verificare l’identità degli utenti ai fini dell’accesso a sistemi informatici (es. dimissioni dipendente, servizio terminato dal cliente, voltura del servizio, contratto terminato o rescisso); tale azione viene quindi a integrarsi alla disattivazione dell''''utenza a cui è associata la password.\\\\\\\\n\\\\\\\\nDopo la cancellazione non deve essere possibile autenticare l''''utenza (il valore eventualmente conservato nei sistemi centralizzati di autenticazione al posto della password non deve corrispondere a nessun valore che può essere inserito dall''''utente in fase di autenticazione).','','','MUST','LGA','','','','','si'),
  ('SEC-AC7-002.03','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Algoritmi di protezione delle password - digest','Ad integrazione della tabella presente in SEC-AC7-002.01, per consentire una maggior robustezza (quantum-safe) degli algoritmi adottati rispetto ad attacchi di tipo store and decrypt, la dimensione del digest utilizzato dagli algoritmi di protezione delle password deve essere pari ad almeno 512 bit.','','','SHOULD','LGA','','','','','si'),
  ('SEC-AC7-003.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Strong authentication per utenti interni','L''''accesso interattivo degli utenti ad applicazioni o sistemi di Azienda deve essere protetto mediante meccanismi di autenticazione forte (a due fattori).\\\\\\\\nEventuali deroghe devono essere esplicitamente autorizzate e sono possibili solo a fronte di un livello di rischio basso o di una impossibilità tecnica o operativa all''''uso di un secondo fattore.','Sistemi aziendali interni di autenticazione','','MUST','LGA','','','','','si'),
  ('SEC-AC7-003.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Secondo fattore di autenticazione','I secondi fattori di autenticazione approvati sono:\\\\\\\\n - OTP\\\\\\\\n - smart card certificata EAL4+\\\\\\\\n - smart card virtuale basata su TPM','','','MUST','LGA','','','','','si'),
  ('SEC-AC7-003.02','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','OTP','L''''uso di OTP deve prevedere in alternativa:\\\\\\\\n\\\\\\\\n - un sistema di generazione continuo di OTP a scadenza temporale fissa (30 o 60 secondi) basato sull''''uso di una app per dispositivi (e.g. app TOTP aziendale) e di un sistema centralizzato, sincronizzati tramite protocollo TOTP\\\\\\\\n - la generazione e invio di un OTP, utilizzabile una sola volta e con scadenza limitata:\\\\\\\\n   + in caso di invio tramite SMS, massimo 5 min.\\\\\\\\n    + in caso di invio tramite mail, a non più di 15 minuti\\\\\\\\n   l''''invio deve essere effettuato all''''utente tramite il canale di contatto preferenziale tra quelli validati.\\\\\\\\n\\\\\\\\nLa lunghezza dell''''OTP generato deve essere di almeno 6 caratteri.\\\\\\\\n\\\\\\\\nL''''invio tramite mail non è robusto quanto gli altri metodi descritti va quindi evitato quando possibile. In caso l''''OTP debba essere parte di una autenticazione a 2 fattori, l''''invio via mail non è utilizzabile.','','','MUST','LGA','','','','','si'),
  ('SEC-AC7-004.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Utilizzo OTP','E'''' necessario prevedere l''''utilizzo di OTP (preferibilmente App TOTP, dove utilizzata o mediante token inviato ai canali di contatto SMS/Mail) per i seguenti casi:\\\\\\\\n\\\\\\\\nAutenticazione\\\\\\\\n\\\\\\\\n - Attivazione e Disattivazione altri metodi di autenticazione (Social, Remember me, altro)\\\\\\\\n - Generazione Alias\\\\\\\\n - Generazione Token di autenticazione (es Apptoken PEC +) *\\\\\\\\n - Attivazione funzionalità "Remember Me"\\\\\\\\n - Reset Password \\\\\\\\n - Cambio Password\\\\\\\\n\\\\\\\\nConfigurazione\\\\\\\\n\\\\\\\\n - Disattivazione 2FA *\\\\\\\\n - Configurazioni di rilievo da pannello amministrativo o PGA in particolare la modifica di canali di contatto (mail e cellulare)*\\\\\\\\n - Gestione dispositivo\\\\\\\\n   + Aggiunta nuovo dispositivo\\\\\\\\n   + Rimozione dispositivo\\\\\\\\n\\\\\\\\n*richieste per le quali  è necessario un OTP per ogni singola operazione.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','documentazione interna','MUST','LGA','','','','','si'),
  ('SEC-AC7-005.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Logiche Anti Automation e Brute forcing ','Devono essere previsti opportuni meccanismi di controllo per evitare tentativi di brute forcing automatizzati nei casi in cui:\\\\\\\\n\\\\\\\\n1. Reiterare sistematicamente l''''inserimento di dati permette di enumerare dati reali presenti nel sistema (esempio: inserendo un valore in una form il sistema dà un risultato differente se il valore corrisponde o no ad un dato già presente nel sistema; brute force)\\\\\\\\n2. l''''inserimento di dati comporta l''''impiego di risorse significative, vi è la possibilità di esaurire risorse o fare un uso improprio del sistema (esempio: registrare un elevato numero di utenti; generare messaggi, log, allarmi o altre segnalazioni; inserire commenti o altre informazioni per ingannare o influenzare il lettore, etc.)\\\\\\\\n\\\\\\\\nLa protezione, in ordine decrescente di preferenza, consiste in:\\\\\\\\n1. inserimento dei dati solo dopo autenticazione;\\\\\\\\n2. metodi integrati nell''''applicazione per limitare la frequenza o il numero di azioni di inserimento dati (throttling cioè blocco temporaneo per tempi progressivamente più lunghi dopo un certo numero di tentavi errati, numero massimo di tentativi, etc.);\\\\\\\\n3. metodi esterni di identificazione di bot (anti bot e CAPTCHA standard aziendale, fino a diversa indicazione si usa il captcha di Google)','','Sono da valutare caso per caso le deroghe basate su interazioni provenienti da sorgenti sicure (utilizzabile solo dall''''interno di Azienda o di terze parti fidate)\\\\\\\\nPer il throttling, vedi standard CIAM documentazione interna','MUST','RIF-111
LGA','','si','','','si'),
  ('SEC-AC7-006.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Processi di gestione delle credenziali utente','Devono essere previsti dei processi per la gestione delle credenziali di accesso degli utenti, al fine di:\\\\\\\\n\\\\\\\\nrecuperare gli identificativi\\\\\\\\nmodificare le password di accesso\\\\\\\\nrecuperare l''''accesso in caso di perdita dei fattori di autenticazione','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-006.01','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Recupero fattore di identificazione','Con "fattore di identificazione" si intende l''''elemento inserito dagli utenti a scopo di identificazione dell''''utente stesso, comunemente indicato come nome utente o username.\\\\\\\\n\\\\\\\\nIl recupero del fattore di identificazione deve richiedere l''''inserimento di un canale di contatto precedentemente validato a cui inviare l''''indicazione dei fattori di identificazione associati al canale.\\\\\\\\n\\\\\\\\nLe informazioni fornite del sistema nell''''interfaccia di recupero informazioni non devono rivelare se i dati inseriti per il recupero sono corretti o errati. Vedi anche requisito SEC-AC7-005.00.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','Vedi processo descritto in Recupero Credenziali Primarie - New Enterprise Application Architecture - Confluence','MUST','LGA','','','','','si'),
  ('SEC-AC7-006.02','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Cambio password','Il cambio di una password utente richiede:\\\\\\\\n\\\\\\\\nche l''''utente si trovi in una sessione autenticata;\\\\\\\\nche l''''utente inserisca la password precedente, oltre alla nuova password;\\\\\\\\nche la nuova password sia verificata con un secondo inserimento;\\\\\\\\nse è attiva la 2FA, che l''''utente inserisca la credenziale relativa al secondo fattore.\\\\\\\\nL''''utente deve essere notificato su tutti i canali di contatto presenti in anagrafica dell''''avvenuto cambio password \\\\\\\\n\\\\\\\\nA seguito del cambio password, tutte le sessioni utente attive devono essere chiuse, ad eccezione della sessione con cui è stato svolto il cambio password. Le attivazioni di Remember me devono essere resettate.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','Vedi processo descritto in MODIFICA CREDENZIALI PRIMARIE ACU e INTRANET - New Enterprise Application Architecture - Confluence','MUST','LGA','','','','','si'),
  ('SEC-AC7-006.03','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Reset password','Il reset di una password utente richiede: \\\\\\\\n\\\\\\\\nl''''inserimento da parte dell''''utente del proprio fattore di identificazione;\\\\\\\\nl''''invio ad un canale di contatto dell''''utente (preferibilmente validato) di un OTP o di un deep link per proseguire con il processo di reset;\\\\\\\\nl''''impostazione della password da parte dell''''utente.\\\\\\\\nL''''utente deve essere notificato su tutti i canali di contatto presenti in anagrafica dell''''avvenuto reset password.\\\\\\\\n\\\\\\\\nLa risposta del sistema a seguito di errore nell''''inserimento del fattore di identificazione deve essere generica e non deve rivelare se i dati inseriti per il reset sono corretti o errati. Vedi anche requisito SEC-AC7-005.00.\\\\\\\\n\\\\\\\\nA seguito del reset della password, tutte le sessioni utente attive devono essere chiuse e le attivazioni di Remember me devono essere resettate.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','Vedi processo descritto in Recupero Credenziali Primarie - New Enterprise Application Architecture - Confluence','MUST','LGA','','','','','si'),
  ('SEC-AC7-006.04','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Sostituzione dispositivo di autenticazione forte','La sostituzione di uno strumento di autenticazione forte richiede la conferma dell''''identità mediante:\\\\\\\\n\\\\\\\\nun OTP tramite SMS inviato al canale di contatto telefonico validato dell''''utente\\\\\\\\noppure mediante dispositivo di autenticazione con livello di autenticazione uguale o superiore rispetto al dispositivo che si va a cambiare.\\\\\\\\nA seguito della sostituzione, deve essere inviata una notifica, per un eventuale disconoscimento, a tutti i canali di contatto validati dell''''utente presenti in anagrafica.\\\\\\\\n\\\\\\\\nNOTA: la cancellazione dell''''informazione relativa ad uno strumento di autenticazione può essere effettuata solo a seguito del completamento delle corretta registrazione del nuovo strumento.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-007.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Modalità di generazione credenziali','L''''accesso ai sistemi deve avvenire a seguito dell''''identificazione dell''''utente per mezzo di credenziali a lui assegnate in modo esclusivo.\\\\\\\\n\\\\\\\\nLa segretezza di tali credenziali deve essere rigorosamente preservata fin dalla fase di creazione dell''''utenza, adottando una delle seguenti modalità:\\\\\\\\n\\\\\\\\n1 - Password provvisoria con cambio obbligatorio al primo accesso:\\\\\\\\n\\\\\\\\nL''''utente riceve una password provvisoria in fase di registrazione o di creazione dell''''account. Al primo accesso, la password provvisoria deve essere sostituita con una nuova password di sua scelta. In fase di generazione, deve essere garantito che password venga consegnata all''''utente con canale confidenziale.\\\\\\\\n\\\\\\\\n2 - Inserimento della password da parte dell''''utente durante la registrazione:\\\\\\\\n\\\\\\\\nDurante la registrazione, l''''utente è personalmente responsabile dell''''inserimento della password di autenticazione.','','','MUST','LGA','','','','','si'),
  ('SEC-AC7-008.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Accesso tramite link univoco','Laddove l''''accesso a pagine con informazioni personali è realizzato tramite link contenenti una stringa univoca e senza ulteriore autenticazione, devono essere rispettati i seguenti requisiti:\\\\\\\\n\\\\\\\\n - includere come stringa univoca un nonce crittografico che sia lungo almeno 32 byte e dotato di caratteristiche di aleatorietà, garantite da opportune librerie crittografiche\\\\\\\\n - avere una scadenza commisurata all''''utilizzo previsto ma comunque non superiore a 72 ore\\\\\\\\n - se accessibili da Internet, deve essere rispettato il requisito SEC-PT3-002.00 (protezione da indicizzazione)\\\\\\\\n\\\\\\\\nEsempi di questo tipo di funzionalità sono: link per reset password o per primo accesso ad un servizio, rinnovo di un servizio senza autenticazione, link utilizzati dai sistemi di archiviazione per la condivisione di file, etc.\\\\\\\\n\\\\\\\\nL''''uso di questa metodologia di accesso deve essere evitata ove possibile.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-008.01','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Informazioni personalizzate di riconoscimento nelle pagine accessibili tramite link univoco','Le comunicazioni alla clientela devono evitare l''''uso di link univoci accessibili senza autenticazione, in particolare quando la pagina di atterraggio richiede l''''inserimento di dati riservati (es. dati di pagamento, autenticazione, cambio password, etc.)\\\\\\\\n\\\\\\\\nQuando questo requisito non è applicabile per stringenti necessità di gestione della clientela, i rischi di phishing vanno mitigati con l''''inserimento, nella pagina di atterraggio del link, di un elemento noto solo al cliente e/o da lui precedentemente scelto allo scopo (es. foto, avatar, icona, alias dello user, etc.) in modo che sia facilitato il riconoscimento dell''''autenticità del sito Azienda da parte del cliente.\\\\\\\\n\\\\\\\\nIstruzioni specifiche devono essere fornite ai clienti in modo da massimizzare l''''efficacia di tale presidio.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-009.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Notifica dell''''accesso precedente','Nella pagina di atterraggio dopo la login dei clienti ai servizi devono essere visualizzate data e ora del precedente  acceso.\\\\\\\\n\\\\\\\\nContestualmente alla visualizzazione di data e ora, deve essere visualizzato un link di aiuto e un link alla pagina di segnalazione accessi sospetti.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','SHOULD','LGA','','','','','si'),
  ('SEC-AC7-010.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Remember me','La funzionalità "Remember me" permette ad un utente di abilitare l''''accesso diretto (senza autenticazione esplicita) al proprio account su un dispositivo specifico.\\\\\\\\n\\\\\\\\nIn caso di 2FA non attiva o non presente:\\\\\\\\n\\\\\\\\nal termine di una autenticazione andata a buon fine, l''''applicazione può richiedere all''''utente se attivare il "Remember me" su quel dispositivo. In caso di risposta positiva, all''''utente non verrà richiesto di inserire nuovamente le credenziali ai successivi accessi dallo stesso dispositivo.\\\\\\\\n\\\\\\\\nIn caso di 2FA attiva:\\\\\\\\n\\\\\\\\nal termine di una autenticazione andata a buon fine, l''''applicazione può richiedere all''''utente se attivare il "Remember me" su quel dispositivo. In caso di risposta positiva, all''''utente non verrà richiesto di inserire nuovamente le credenziali (includendo sia il primo che il secondo fattore di autenticazione) ai successivi accessi dallo stesso dispositivo.\\\\\\\\n\\\\\\\\nIn caso di attivazione della 2FA successiva all''''attivazione del "Remember me", la funzionalità di "Remember me" deve essere disattivata su tutti i dispositivi ed eventualmente riattivata dopo una nuova autenticazione.\\\\\\\\n\\\\\\\\nLa funzionalità "Remember me" deve avere una scadenza, per ciascun dispositivo, non superiore a 6 mesi; tale scadenza viene rinnovata ad ogni accesso. Se non viene effettuato nessun accesso prima della scadenza, il "Remember me" viene cancellato.\\\\\\\\n\\\\\\\\nIl servizio deve permettere al cliente di visualizzare e revocare la funzionalità "Remember me" per ciascun dispositivo abilitato.\\\\\\\\n\\\\\\\\nNella pagina di visualizzazione, all''''utente deve essere presentata una descrizione sintetica del dispositivo ablitato, comprendente:\\\\\\\\n\\\\\\\\nbrowser (modello e versione)\\\\\\\\nsistema operativo (tipo e versione)\\\\\\\\ngeolocalizzazione\\\\\\\\ndata e ora dell''''ultimo accesso','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','NOTA: le interazioni con RBA implementano parzialmente la funzionalità di "Remember me" in quanto RBA permette di non richiedere tutti i fattori di autenticazione in caso di rischio basso\\\\\\\\nVedi anche AUTENTICAZIONE E2E - New Enterprise Application Architecture - Confluence','SHOULD','LGA','','','','','si'),
  ('SEC-AC7-011.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Canali di contatto','Per "canale di contatto" si intende uno strumento di comunicazione fornito dal cliente che permette l''''invio di comunicazioni al cliente.\\\\\\\\n\\\\\\\\nPer "canale di contatto validato" si intende un canale di contatto di cui è stato verificato il possesso da parte dell''''utente.\\\\\\\\n\\\\\\\\nEsempi di canali di contatto sono:\\\\\\\\n - casella email\\\\\\\\n - numero di telefono, per la ricezione di SMS o di chiamate vocali\\\\\\\\n - app in grado di ricevere notifiche','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-011.01','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Gestione canali di contatto','Devono essere previsti i seguenti casi d''''uso con i relativi messaggi di validazione, autorizzazione e notifica:\\\\\\\\n\\\\\\\\n - Inserimento iniziale del canale di contatto: in fase di registrazione del cliente, questo compila l''''apposito form con le informazioni sui suoi canali di contatto.	\\\\\\\\nValidazione: facoltativa; devono essere inviati automaticamente dei messaggi che permettono la validazione facoltativa dei canali di contatto inseriti dall''''utente\\\\\\\\nAutorizzazione: N/A\\\\\\\\nNotifica: N/A\\\\\\\\n\\\\\\\\n - Aggiornamento del canale di contatto in fase di primo accesso all''''area clienti: il canale di contatto precedentemente inserito deve essere mostrato all''''utente per conferma ed eventuale correzione.\\\\\\\\nValidazione: obbligatoria; se i canali di contatto non sono già stati validati, per procedere con l''''accesso ad un pannello tecnico o all''''area clienti deve essere obbligatoriamente  effettuata la validazione di almeno un canale di contatto..\\\\\\\\nAutorizzazione: N/A\\\\\\\\nNotifica: se viene modificato il canale di contatto precedentemente inserito, inviata a tutti i canali di contatto dell''''utente, incluso quello precedentemente inserito e soggetto a modifica.\\\\\\\\n\\\\\\\\n - Aggiunta canali di contatto: all''''interno dell''''Area Clienti; sempre possibile\\\\\\\\nValidazione: facoltativa; solo per canali di contatto che si vogliono validare.\\\\\\\\nAutorizzazione: facoltativa; solo per canali di contatto che si vogliono validare; la validazione va a buon fine solo se viene autorizzata su un canale già validato.\\\\\\\\nNotifica: obligatoria; inviata a tutti i canali di contatto dell''''utente.\\\\\\\\n\\\\\\\\n - Modifica canali di contatto validati: all''''interno dell''''Area Clienti; sempre possibile\\\\\\\\nValidazione: obbligatoria\\\\\\\\nAutorizzazione: obbligatoria; su uno dei canali precedentemente validati (incluso quello soggetto a modifica), a scelta dell''''utente\\\\\\\\nNotifica: obbligatoria; inviata a tutti i canali di contatto dell''''utente, incluso quello precedentemente inserito e soggetto a modifica.\\\\\\\\n\\\\\\\\n - Modifica / cancellazione canali di contatto non validati: all''''interno dell''''Area Clienti; sempre possibile	\\\\\\\\nValidazione: facoltativa; solo se si vuole validare il nuovo canale di contatto.\\\\\\\\nAutorizzazione: facoltativa; solo per canali di contatto che si vogliono validare; la validazione va a buon fine solo se viene autorizzata su un canale già validato.\\\\\\\\nNotifica: obbligatoria; inviata a tutti i canali di contatto dell''''utente.\\\\\\\\n\\\\\\\\n - Cancellazione canali di contatto validati: all''''interno dell''''Area Clienti; possibile solamente se sono presenti altri canali validati.\\\\\\\\nValidazione: N/A	\\\\\\\\nAutorizzazione: obbligatoria; su uno dei canali precedentemente validati (incluso quello soggetto a cancellazione), a scelta dell''''utente\\\\\\\\nNotifica: obbligatoria; inviata a tutti i canali di contatto dell''''utente, incluso quello soggetto a cancellazione.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','Vedasi anche VALIDAZIONE CANALI DI CONTATTO - New Enterprise Application Architecture - Confluence\\\\\\\\n\\\\\\\\nLa non obbligatorietà della validazione dei canali di contatto al momento dell''''inserimento iniziale è una eccezione prevista solo per il CIAM di Identity Core.','MUST','LGA','','','','','si'),
  ('SEC-AC7-011.02','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Trattamento dei dati di contatto','I dati di contatto acquisiti mediante form online devono essere validati prima di essere utilizzati (ad esempio mediante magic link inviato all''''indirizzo mail o OTP inviato al numero di telefono). \\\\\\\\n\\\\\\\\nLa creazione di un account deve prevedere la validazione del canale di contatto (mail/telefono) prima di essere attivato.\\\\\\\\n\\\\\\\\nI meccanismi di validazione devono avere una valenza temporale massima, come da requisito SEC-AC7-003.02, oltre la quale, in assenza di utilizzo, è necessario inviare un nuovo link o OTP di validazione.\\\\\\\\n\\\\\\\\nFinché il canale non viene validato, i consensi al trattamento dei dati eventualmente conferiti non possono considerarsi validi.\\\\\\\\n\\\\\\\\nNel caso in cui i dati di contatto raccolti non siano stati validati dal cliente entro 24 ore, il cliente deve ricominciare ex novo la registrazione e i dati preliminarmente acquisiti devono essere cancellati.','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','','','','','',''),
  ('SEC-AC7-012.00','1','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Validazione e autorizzazione','La validazione e autorizzazione delle operazioni utente rilevanti (validazione dei canali di contatto, autorizzazione accesso rischioso, etc.) devono avvenire secondo una delle seguenti modalità:\\\\\\\\n\\\\\\\\n - con messaggio SMS, contenente un OTP da riportare in una schermata dell''''applicazione\\\\\\\\n - con messaggio mail, contenente sia un OTP da riportare in una schermata dell''''applicazione sia un link dinamico, univoco e temporaneo, che, se richiamato, confermi la ricezione del messaggio o l''''autorizzazione all''''operazione\\\\\\\\n - con notifica in app, in cui viene richiesta una conferma dell''''azione\\\\\\\\n\\\\\\\\nL''''OTP deve essere generato secondo quanto definito nel requisito SEC-AC7-003.02\\\\\\\\n\\\\\\\\nIl link dinamico deve essere generato secondo quanto previsto nel requisito SEC-AC7-008.00','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-013.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Creazione di account cliente da parte di operatori','Se sono previsti processi di creazione di un account per conto del cliente svolte da operatori Azienda utilizzando dati forniti telefonicamente dal cliente, il processo deve rispettare i seguenti vincoli:\\\\\\\\n\\\\\\\\n - L’operatore deve svolgere l''''attività su un pannello dedicato\\\\\\\\n - Il sistema deve inviare un OTP via SMS al cliente per richiedere l’autorizzazione a questa attività\\\\\\\\n - Il testo dello stesso SMS deve descrivere l''''attività che si sta autorizzando e deve contenere il link dell’informativa privacy\\\\\\\\n - L’avvio della procedura di creazione dell''''account deve iniziare a seguito della comunicazione all''''operatore dell''''OTP ricevuto dal cliente tramite SMS e della sua verifica sul sistema\\\\\\\\n - I dati di contatto del cliente (cellulare e indirizzo email) devono essere validati tramite l''''invio di OTP per ciascuno dei canali di contatto\\\\\\\\n - L''''account deve essere creato solo in seguito alla validazione da parte del cliente dei canali di contatto\\\\\\\\n - L’account del cliente deve essere attivato con una password pre-scaduta da cambiare al primo accesso oppure un OTP / link per generare la password in autonomia (fare riferimento al req. SEC-AC7-007.00)\\\\\\\\n - L''''operatore non deve poter impostare la password del cliente\\\\\\\\n - Non deve essere possibile per l’operatore variare i dati di contatto validati dal cliente con gli OTP salvo nuova procedura validata dal cliente \\\\\\\\n - Non si devono chiedere al cliente i consensi privacy, se si vogliono richiedere, è obbligatorio inviare un OTP via telefono per ogni consenso privacy\\\\\\\\n - Ogni azione dell’operatore e del cliente deve essere loggata e conservata per 10 anni\\\\\\\\n - Gli OTP devono rispettare il requisito SEC-AC7-003.02','Sistemi CIAM (Customer Identity & Access Management) o equivalenti','','MUST','LGA','','','','','si'),
  ('SEC-AC7-014.00','2','Identity Management, Authentication and Access Control (PR.AC)','PR.AC-7: Le modalità di autenticazione (es. autenticazione a fattore singolo o multiplo) per gli utenti, i dispositivi e altri asset sono commisurate al rischio della transazione (es. rischi legati alla sicurezza e privacy degli individui e altri rischi dell''''organizzazione)','Numero massimo di sessioni utente','Il numero massimo di sessioni utente contemporaneamente attive deve essere controllabile e configurabile. Quando viene raggiunto il numero massimo di sessioni consentite, la sessione più vecchia tra quelle aperte deve essere chiusa.\\\\\\\\n\\\\\\\\nDi default, il numero massimo di sessioni consentite per le utenze comuni deve essere pari a 10; per le utenze dotate di privilegi elevati (sia utenze interne di Azienda che utenze dei clienti) deve essere pari a 1. Un numero maggiore può essere consentito solo a fronte di una analisi di usabilità.\\\\\\\\n\\\\\\\\nAd esempio, si considerano utenze privilegiate::\\\\\\\\n\\\\\\\\n - le utenze interne con diritti amministrativi che accedono ai sistemi tramite macchina ponte\\\\\\\\n\\\\\\\\n - le utenze di operatori, partner e rivenditori con diritti di creazione o modifica del profilo dei clienti\\\\\\\\n\\\\\\\\n - le utenze dei clienti con diritti di amministrazione del proprio servizio (postmaster, etc.)','Sistemi aziendali interni di autenticazione\\\\\\\\n\\\\\\\\nSistemi CIAM (Customer Identity & Access Management) o equivalenti','documentazione interna','MUST','LGA','DC - RUN','','','si','si'),
  ('SEC-DS1-001.00','1','Data Security (PR.DS)','PR.DS-1: I dati memorizzati sono protetti','Conservazione dei documenti di identità dei clienti','Le copie dei documenti di identità ed i documenti richiesti ai fini del riconoscimento gestiti dal servizio (inteso come richiamati / mostrati a front end, tramite il servizio) devono essere conservati sull''''infrastruttura centralizzata di storage appositamente realizzata per questo scopo (Shared Object storage / Conservazione sostitutiva) al fine di garantire l''''implementazione corretta dei meccanismi di sicurezza necessari (controllo accessi, cifratura, retention, audit, ecc.) e quindi evitare di doverli re-implementare per ogni servizio.\\\\\\\\n\\\\\\\\nE'''' necessario ingaggiare il reparto Data Protection (su Jira: task DP - consulenza) al fine di definire i tempi di retention.','','','MUST','LGA','','','','','si'),
  ('SEC-DS1-002.00','2','Data Security (PR.DS)','PR.DS-1: I dati memorizzati sono protetti','Protezione dati particolari e giudiziari','Dati giudiziari e particolari devono essere cifrati e, ove possibile, trattati con apposite tecniche di anonimizzazione (ad esempio, con pseudonimi o offuscamento).','','','MUST','LGA','','','','','si'),
  ('SEC-DS1-003.00','1','Data Security (PR.DS)','PR.DS-1: I dati memorizzati sono protetti','Finestre temporali di accesso ai dati personali','L''''accesso ai dati personali da parte degli operatori deve essere concesso in relazione alle fasi del ciclo di vita del servizio; ad esempio, gli OdR non devono vedere più i dati dei documenti di riconoscimento successivamente all''''attivazione del servizio.','','','MUST','LGA','','','','','si'),
  ('SEC-DS1-004.00','1','Data Security (PR.DS)','PR.DS-1: I dati memorizzati sono protetti','Share di rete','L''''uso delle share di rete per la condivisione dei dati deve essere limitato al minimo indispensabile. In particolare:\\\\\\\\n - l''''attivazione e l''''uso delle share di rete basate su protocollo SMB (DFS, CIFS) dai sistemi client è vietata.\\\\\\\\n - l''''uso di share nella condivisione tra server è ammessa con protocolli differenti da SMB.\\\\\\\\nPer lo scambio di dati o documenti tra persone è preferibile il ricorso a strumenti aziendali di condivisione come strumenti aziendali di condivisione.\\\\\\\\nL''''accesso alle share deve essere comunque concesso solo agli utenti o alle applicazioni che ne hanno necessità; l''''accesso deve essere richiesto al gruppo IAM tramite apposito task.','','','MUST','LGA','','','','','si'),
  ('SEC-DS2-001.00','1','Data Security (PR.DS)','PR.DS-2: I dati sono protetti durante la trasmissione','Utilizzo Protocolli Sicuri','Tutte le trasmissioni di dati (per qualunque tipologia di accesso e per qualunque tipologia di utente) devono utilizzare protocolli di rete cifrati, robusti e non obsoleti','','','MUST','RIF-103
LGA
Change','','si','si','','si'),
  ('SEC-DS2-001.01','1','Data Security (PR.DS)','PR.DS-2: I dati sono protetti durante la trasmissione','Interfacce web','Le interfacce web devono esporre i servizi usando TLS 1.2 o 1.3 e devono fare uso dei certificati gestiti dalle CA di Azienda.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-DS2-001.02','1','Data Security (PR.DS)','PR.DS-2: I dati sono protetti durante la trasmissione','Accesso in console','Le interfacce di accesso in console ai sistemi devono utilizzare protocolli di rete cifrati, robusti e non obsoleti, ad esempio SSH 2 o RDP basato su TLS 1.2 o 1.3.','','','MUST','','','','','',''),
  ('SEC-DS2-001.03','1','Data Security (PR.DS)','PR.DS-2: I dati sono protetti durante la trasmissione','Trasmissione dati','La trasmissione dei dati deve utilizzare meccanismi di cifratura dei flussi tramite protocolli di rete cifrati, robusti e non deprecati, ad esempio SFTP o FTPS basato su TLS 1.2 o 1.3.','','','MUST','LGA','','','','','si'),
  ('SEC-DS2-001.04','1','Data Security (PR.DS)','PR.DS-2: I dati sono protetti durante la trasmissione','API','Le API devono esporre i servizi usando TLS 1.2 o 1.3 e devono fare uso dei certificati gestiti dalle CA di Azienda.','','','MUST','LGA','','','','','si'),
  ('SEC-DS2-002.00','1','Data Security (PR.DS)','PR.DS-2: I dati sono protetti durante la trasmissione','Configurazione cifratura protocolli di rete','Le configurazioni di default relative ai meccanismi di cifratura dei protocolli di rete (chiavi, certificati, etc.) devono poter essere modificate al fine di utilizzare certificati emessi dalle CA di Azienda.','','','MUST','Change','','','si','',''),
  ('SEC-DS5-001.00','1','Data Security (PR.DS)','PR.DS-5: Sono implementate tecniche di protezione (es. controllo di accesso) contro la sottrazione dei dati (data leak).','Protezione servizi HTTP / HTTPS esposti all''''esterno','Per ogni elemento esposto al WEB o il cui indirizzo IP sia oggetto di NAT su indirizzi IP pubblici Azienda accessibili dall''''esterno, è necessario prevedere l''''integrazione della risorsa esposta con l''''opportuno WAF di produzione verificando sia la corretta funzionalità sia il corretto tracciamento dei sorgenti IP di origine, come ad esempio l''''IP cliente.\\\\\\\\n\\\\\\\\nÈ necessario nel caso di utilizzo del WAF Fortinet che l''''applicazione o il web server siano in grado di gestire il parametro X-Forwarded-For comunicato tramite header HTTP.\\\\\\\\n\\\\\\\\nVerificare quindi che i log applicativi e di sistema traccino i corretti indirizzi IP nonostante il transito della connessione attraverso il WAF.','Si applica anche alle API esposte pubblicamente','Per le terminazioni TLS su WAF, vale quanto pubblicato nel requisito SEC-DS2-001.01','MUST','RIF-110
LGA','','si','','','si'),
  ('SEC-DS5-001.01','1','Data Security (PR.DS)','PR.DS-5: Sono implementate tecniche di protezione (es. controllo di accesso) contro la sottrazione dei dati (data leak).','Protezione servizi HTTP / HTTPS esposti all''''esterno - Verifica su IP antibruteforce','In caso l''''applicazioni presenti meccanismi antibruteforcing attivi, è necessario verificare sia nei log che nelle chiamate del servizio di antibruteforcing che l''''indirizzo IP tracciato sia l''''indirizzo IP sorgente e non quello del WAF (utilizzando ad esempio il parametro X-Forwarded-For) ','','','MUST','LGA','','','','','si'),
  ('SEC-DS5-001.02','2','Data Security (PR.DS)','PR.DS-5: Sono implementate tecniche di protezione (es. controllo di accesso) contro la sottrazione dei dati (data leak).','Protezione servizi HTTP / HTTPS esposti all''''esterno - Bilanciatori','I meccanismi di persistenza delle sessioni utente devono essere compatibili con le configurazioni di produzione di bilanciatori e WAF.','','Ad esempio, i meccanismi di persistenza di sessione prevedono in taluni casi il salvataggio dell''''identificativo di sessione in memoria. La mancata persistenza legata all''''utilizzo del WAF come bilanciatore può rendere necessaria la storicizzazione in DB delle informazioni di sessione.','MUST','LGA','','','','','si'),
  ('SEC-DS5-002.00','1','Data Security (PR.DS)','PR.DS-5: Sono implementate tecniche di protezione (es. controllo di accesso) contro la sottrazione dei dati (data leak).','Mascheramento dati di contatto','Quando è necessario mostrare uno o più dati di contatto in una sessione non autenticata, ad esempio in fase di recupero password, i dati di contatto devono essere sempre mascherati, lasciando visibili soltanto:\\\\\\\\n\\\\\\\\n - per gli indirizzi email: i primi 2 caratteri e l''''ultimo carattere del nome della casella ed il dominio nella sua interezza\\\\\\\\n - per i numeri di telefono: il prefisso internazionale (se necessario) e le ultime 3 cifre','','','MUST','LGA','','','','','si'),
  ('SEC-DS5-003.00','1','Data Security (PR.DS)','PR.DS-5: Sono implementate tecniche di protezione (es. controllo di accesso) contro la sottrazione dei dati (data leak).','Minimizzazione dei dati','Possono essere conservati solo i dati strettamente necessari per i soli scopi legittimi e specifici dell''''organizzazione, definendo e documentando con precisione le finalità per cui i dati sono necessari. Tale fine si ottiene ad esempio con le seguenti modalità:\\\\\\\\n\\\\\\\\n - la modalità preferenziale è evitare di memorizzare dati che non sono essenziali\\\\\\\\n - quando è necessario mantenere i dati allora questi devono essere elaborati da apposite procedure di filtro e anonimizzazione o pseudonimizzazione prima di essere resi consultabili al fine di ridurre il rischio di identificazione degli interessati\\\\\\\\n - limitando l''''accesso ai dati ai soli soggetti che ne hanno effettivamente necessità/autorizzazione/formazione per il corretto trattamento, adottando meccanismi di controllo accessi e/o cifratura dei dati medesimi (vedi anche SEC-AC4-003.00)\\\\\\\\n - limitando la conservazione dei dati al tempo minimo indispensabile, in seguito al quale si deve provvedere alla eliminazione sicura dei dati stessi\\\\\\\\n\\\\\\\\nPer i sistemi che effettuano attività di aggregazione e centralizzazione dei dati (es. datawarehouse, sistemi di analisi statistica, sistemi di monitoraggio), deve essere fatta particolare attenzione a che i dati raccolti dai sistemi e dai database utilizzati per le attività operative siano sottoposti a procedure di filtraggio e anonimizzazione (in caso di dati personali).','','','MUST','LGA','','','','','si'),
  ('SEC-DS5-004.00','1','Data Security (PR.DS)','PR.DS-5: Sono implementate tecniche di protezione (es. controllo di accesso) contro la sottrazione dei dati (data leak).','Messaggi di risposta a situazioni di errore','Tutte le condizioni d''''errore devono essere gestite opportunamente. I messaggi di risposta a situazioni di errore non devono contenere informazione aggiuntive rispetto a quanto inserito dall''''utente né fornire indicazioni specifiche sulle risorse non trovate o non accessibili o sulle condizioni che hanno generato l''''errore stesso.','','Esempi di messaggi di risposta a situazioni d''''errore comuni:\\\\\\\\n\\\\\\\\n - in caso di autenticazione fallita, il sistema deve rispondere con un messaggio neutro (“Le credenziali non sono corrette”), senza rivelare quale elemento sia errato.\\\\\\\\n - nelle procedure di recupero credenziali, la risposta deve rimanere non deterministica ("Se i dati inseriti sono corretti, riceverai un link per il reste della password..."), senza rivelare se lo username o la mail inseriti sono effettivamente registrati\\\\\\\\n\\\\\\\\nIl requisito si applica anche alle API: quando la distinzione tra codici di errore (es. 401, 403 o 404) potrebbe rivelare informazioni sullo stato delle risorse, deve essere restituito un codice generico (es. 400) accompagnato da un messaggio neutro.','MUST','LGA','','','','','si'),
  ('SEC-DS6-001.00','1','Data Security (PR.DS)','PR.DS-6: Sono impiegati meccanismi di controllo dell''''integrità dei dati per verificare l''''autenticità di software, firmware e delle informazioni','Verifica dell''''integrità degli artefatti software','Devono essere implementati dei meccanismi di controllo dell''''integrità e dell''''autenticità degli artefatti software lungo tutta la catena di sviluppo, dalle fasi di acquisizione o produzione del software fino ad arrivare ai sistemi di produzione.','','','MUST','LGA','','','','','si'),
  ('SEC-DS6-001.01','1','Data Security (PR.DS)','PR.DS-6: Sono impiegati meccanismi di controllo dell''''integrità dei dati per verificare l''''autenticità di software, firmware e delle informazioni','Artefatti software sviluppati internamente','Gli artefatti software prodotti internamente ad Azienda devono essere firmati (tramite opportuni meccanismi di firma del codice) al momento della creazione degli artefatti da parte dei team che li hanno prodotti (e.g. Sviluppo).','','','MUST','LGA','','','','','si'),
  ('SEC-DS6-001.02','1','Data Security (PR.DS)','PR.DS-6: Sono impiegati meccanismi di controllo dell''''integrità dei dati per verificare l''''autenticità di software, firmware e delle informazioni','Artefatti software sviluppati esternamente','Devono essere implementati dei meccanismi di verifica dell''''autenticità degli artefatti software acquisiti dall''''esterno.\\\\\\\\n\\\\\\\\nSe gli artefatti sono firmati dai produttori del software, la firma deve essere verificata prima di poter accettare il software nei repository di codice di Azienda.\\\\\\\\n\\\\\\\\nSe gli artefatti non sono firmati dai produttori, deve essere realizzato un processo di verifica off-line dell''''autenticità di quanto acquisito, documentando le verifiche effettuate e l''''esito ottenuto. Successivamente a tale verifica deve essere apposta una firma agli artefatti così verificati.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-DS6-001.03','1','Data Security (PR.DS)','PR.DS-6: Sono impiegati meccanismi di controllo dell''''integrità dei dati per verificare l''''autenticità di software, firmware e delle informazioni','Verifica della firma in fase di deploy','Il controllo della validità della firma del codice deve essere eseguito al momento dell''''installazione degli artefatti software negli ambienti produttivi.\\\\\\\\n\\\\\\\\nSe il controllo fornisce esito negativo, l''''installazione del software deve essere impedita.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-DS6-001.04','1','Data Security (PR.DS)','PR.DS-6: Sono impiegati meccanismi di controllo dell''''integrità dei dati per verificare l''''autenticità di software, firmware e delle informazioni','Verifica periodica dell''''autenticità','Durante l''''esecuzione del software, deve essere eseguita una verifica periodica di corrispondenza degli artefatti software con la firma.','Qualifica Cloud','','MUST','LGA','','','','','si'),
  ('SEC-IP1-001.00','2','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Linee guide di sicurezza per  i sistemi di posta elettronica','In caso di predisposizione di sistemi di posta elettronica, devono essere seguite le linee guida specificate in nota per la configurazione corretta di tutti i sistemi ed i protocolli di verifica dell''''autenticità delle infrastrutture di posta medesime.','','Linee guida sicurezza per i protocolli di posta: SPF, DKIM, DMARC, ARC','MUST','','','','','',''),
  ('SEC-IP1-002.00','2','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Hardening','Tutte le nuove componenti software (sistemi operativi, database, etc.) devono essere opportunamente sottoposte ad hardening come da linee guida identificate da Sicurezza, attivando solo i servizi strettamente necessari.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-IP1-002.01','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Immagini standard','Devono essere utilizzate le immagini standard hardenizzate già disponibili','','','MUST','LGA','','','','','si'),
  ('SEC-IP1-002.02','3','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Gestione presidi di sicurezza','Devono essere previste l''''installazione e il monitoraggio dei presidi di sicurezza:\\\\\\\\n - agenti (es. EDR, antimalware, client VPN, client DNS, etc.) su server e PC (sono quindi esclusi dispositivi di rete, appliance hardware e software e similari)\\\\\\\\n - funzioni di sicurezza (es. IDS, etc.)\\\\\\\\n - applicazioni o apparati di sicurezza specifici (es. firewall, WAF, gateway DNS sicuro, etc.)','','','MUST','Change','','','si','',''),
  ('SEC-IP1-003.00','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Patching','Tutte le nuove componenti software devono essere predisposte a partire dal massimo livello di patching di sicurezza attualmente disponibile.','','','MUST','LGA','','','','','si'),
  ('SEC-IP1-004.00','3','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Interfacce per accesso  amministrativo','Eventuali interfacce di sistemi, applicazioni o apparati destinate all''''uso amministrativo, alla configurazione o al monitoraggio da parte del personale interno non devono mai essere esposte o raggiungibili da internet.\\\\\\\\n\\\\\\\\nNel caso di sistemi ed apparati, le interfacce amministrative devono essere connesse alle apposite reti di management.\\\\\\\\n\\\\\\\\nNel caso delle applicazioni, le interfacce amministrative devono preferenzialmente essere ospitate su sistemi e reti differenti rispetto a sistemi e reti che ospitano le componenti applicative e le interfacce di erogazione del servizio. Le interfacce amministrative devono inoltre utilizzare protocolli sicuri (vedi requisito SEC-DS2-001.00 e seguenti) per trasmettere le informazioni di configurazione ai sistemi esposti o recuperare i dati da essi.\\\\\\\\n\\\\\\\\nQualora non sia possibile installare le interfacce amministrative su sistemi e reti differenti, è necessario ottenere lo stesso accesso differenziato filtrando le URL amministrative o i protocolli utilizzati, agendo sia a livello applicativo e/o sistemistico, sia tramite l''''inserimento in black list su WAF, in modo che un tentativo di connessione dalla rete internet generi un errore di connessione generico da cui non sia possibile desumere l''''esistenza di tali URL.','','documentazione interna','MUST','LGA
Change','','','si','','si'),
  ('SEC-IP1-005.00','3','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','Ingress Kubernetes','Qualora sia previsto l''''utilizzo di Kubernetes, devono essere rispettate le linee guida di sicurezza pubblicate sotto la pagina Kubernetes - Reparto Sicurezza - Confluence\\\\\\\\n\\\\\\\\nInoltre è necessario rispettare le seguenti indicazioni:\\\\\\\\n\\\\\\\\nNon devono essere utilizzate configurazioni di Ingress di default\\\\\\\\nLe definizioni di Ingress devono essere esplicitate ed indicate all''''interno del progetto. Deve inoltre essere indicato quali endpoint devono essere pubblici e quali privati.','','Kubernetes - Data Center - Confluence','MUST','LGA','','','','','si'),
  ('SEC-IP1-006.00','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-1: Sono definite e gestite delle pratiche di riferimento (c.d. baseline) per la configurazione dei sistemi IT e di controllo industriale che incorporano principi di sicurezza (es. principio di minima funzionalità)','DR - Allineamento infrastruttura','L''''infrastruttura di disaster recovery deve essere allineata con l''''infrastruttura primaria. Ciò include l''''aggiornamento del software, dei driver e dei firmware, nonché l''''aggiornamento dell''''hardware se necessario.','','','MUST','','','','','',''),
  ('SEC-IP2-001.00','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-2: Viene implementato un processo per la gestione del ciclo di vita dei sistemi (System Development Life Cycle).','Linee guide di sicurezza per Sviluppo','Devono essere seguite le linee guida qui elencate al fine di garantire una qualità adeguata in termini di sicurezza:\\\\\\\\n\\\\\\\\nLinee guida per lo sviluppo sicuro\\\\\\\\n\\\\\\\\nLinea guida per lo sviluppo sicuro di Applicazioni Web\\\\\\\\nLinea guida per lo sviluppo sicuro di applicazioni mobile\\\\\\\\nLinee guida per lo sviluppo sicuro in KUBERNETES \\\\\\\\n\\\\\\\\nLinee guida per l''''adozione sicura del framework OPENID-OAUTH2\\\\\\\\nE  \\\\\\\\n\\\\\\\\nLinee guida per l''''offuscamento dati\\\\\\\\nQualsiasi non conformità rispetto alle linee guida sopra indicate dovrà essere segnalata ed approvata dal Reparto Sicurezza','','','MUST','','','','','',''),
  ('SEC-IP4-001.00','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-4: I backup delle informazioni sono eseguiti, amministrati e verificati ','Backup dei dati','Deve essere definita la periodicità con cui eseguire i backup:\\\\\\\\n - di tutti i dati trattati dal servizio\\\\\\\\n - delle configurazioni dei sistemi che erogano il servizio\\\\\\\\n - delle chiavi e dei secrets utilizzati dal servizio\\\\\\\\n - della documentazione del servizio\\\\\\\\nin modo da poter ripristinare completamente il servizio quando necessario.','','','MUST','LGA','','','','','si'),
  ('SEC-IP4-001.01','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-4: I backup delle informazioni sono eseguiti, amministrati e verificati ','Conservazione dei backup','I dati di backup devono essere mantenuti in una area logica e fisica separata rispetto a quella che ospita i dati ed i sistemi oggetto di backup.','','','MUST','','','','','',''),
  ('SEC-IP4-001.02','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-4: I backup delle informazioni sono eseguiti, amministrati e verificati ','BCDR - Conservazione off-site dei backup','Ove richiesto dalle strategie di continuità operativa, i dati di backup devono essere mantenuti in un sito separato rispetto a quello di erogazione.','','','MUST','RIF-101','','si','','',''),
  ('SEC-IP4-001.03','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-4: I backup delle informazioni sono eseguiti, amministrati e verificati ','Verifica dei backup','La correttezza dei backup deve essere verificata e i processi di ripristino per garantire la disponibilità dei dati in caso di perdita o danneggiamento devono essere periodicamente testati.','','','MUST','','','','','',''),
  ('SEC-IP4-001.04','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-4: I backup delle informazioni sono eseguiti, amministrati e verificati ','Accesso ai backup','L''''accesso ai dati di backup deve essere esclusivamente limitato al personale con compiti di manutenzione dei backup e con compiti di ripristino dei dati.','','','MUST','','','','','',''),
  ('SEC-IP4-001.05','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-4: I backup delle informazioni sono eseguiti, amministrati e verificati ','Cancellazione dei backup','La cancellazione delle informazioni di backup deve essere sottoposta a dual control.','','','MUST','','','','','',''),
  ('SEC-IP9-001.00','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-9: Sono attivi ed amministrati piani di risposta (Incident Response e Business Continuity) e recupero (Incident Recovery e Disaster Recovery) in caso di incidente/disastro','BCDR - Pianificazione','Devono essere definiti e documentati gli scenari di indisponibilità che richiedono l''''attivazione di piani di continuità operativa e devono essere descritte le procedure e le azioni necessarie per garantire la continuità del servizio ed il recupero delle funzionalità in caso di emergenza. Nel piano deve essere definita la successione temporale delle attività e delle operazioni di ripristino tenendo conto delle dipendenze funzionali.','','','MUST','LGA','','','','','si'),
  ('SEC-IP9-001.01','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-9: Sono attivi ed amministrati piani di risposta (Incident Response e Business Continuity) e recupero (Incident Recovery e Disaster Recovery) in caso di incidente/disastro','BCDR - ripristini parziali','Il piano deve prevedere le possibili casistiche di ripristini parziali (per solo alcune funzioni, o per solo alcune tipologie di clienti) in base agli SLA contrattuali o ai vincoli normativi. Devono essere elencati e periodicamente aggiornati gli elementi (categorie di utenti, sistemi, etc.) da ripristinare.','','','MUST','LGA','','','','','si'),
  ('SEC-IP9-001.02','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-9: Sono attivi ed amministrati piani di risposta (Incident Response e Business Continuity) e recupero (Incident Recovery e Disaster Recovery) in caso di incidente/disastro','BCDR - funzioni critiche','Tra le funzioni critiche devono essere considerati i requisiti di sicurezza e di monitoraggio.','','','MUST','LGA','','','','','si'),
  ('SEC-IP10-001.00','1','Information Protection Processes and Procedures (PR.IP)','PR.IP-10: I piani di risposta e recupero a seguito di incidenti/disastri sono verificati nel tempo','BCDR - Test','Le procedure di ripristino in emergenza del servizio devono essere testate prima del rilascio in produzione del servizio, e successivamente devono essere verificate periodicamente nell''''ambito del piano annuale di test di DR.\\\\\\\\nI test devono includere scenari di emergenza simulati per verificare l''''efficacia della procedura di ripristino e identificare eventuali problemi.\\\\\\\\nI test devono includere almeno:\\\\\\\\n - test delle componenti funzionali del servizio\\\\\\\\n - test infrastrutturali\\\\\\\\n - test di restore dei dati\\\\\\\\n - test delle procedure operative\\\\\\\\n - test dei piani di comunicazione interna ed esterna','','','MUST','LGA','','','','','si'),
  ('SEC-PT3-001.00','1','Protective Technology (PR.PT)','PR.PT-3: Viene adottato il principio di minima funzionalità configurando i sistemi in modo che forniscano solo le funzionalità necessarie','Funzionalità minime','In tutte le nuove componenti software devono essere attivate esclusivamente le funzionalità e i servizi strettamente necessari','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-PT3-002.00','1','Protective Technology (PR.PT)','PR.PT-3: Viene adottato il principio di minima funzionalità configurando i sistemi in modo che forniscano solo le funzionalità necessarie','Protezione da indicizzazione','L''''indicizzazione delle URL da parte di motori di ricerca pubblici (Google, Bing...) deve essere evitata laddove non necessaria. In questi casi occorre utilizzare le configurazioni prescritte per la NON indicizzazione: file robot.txt, tag noindex e altre tecniche analoghe.','','','MUST','LGA','','','','','si'),
  ('SEC-PT4-001.00','1','Protective Technology (PR.PT)','PR.PT-4: Le reti di comunicazione e controllo sono protette','Controllo dei flussi','I flussi di comunicazione tra sistemi o applicazioni con livelli differente di sicurezza devono essere controllati e ispezionati da firewall e IPS.','','','MUST','RIF-103','','si','','',''),
  ('SEC-PT4-002.00','1','Protective Technology (PR.PT)','PR.PT-4: Le reti di comunicazione e controllo sono protette','Content filtering verso internet','I flussi di comunicazione da e verso internet devono essere mediati tramite appositi proxy che siano in grado di analizzare e validare la correttezza del contenuto scambiato.','','','SHOULD','RIF-103','','si','','',''),
  ('SEC-PT4-003.00','1','Protective Technology (PR.PT)','PR.PT-4: Le reti di comunicazione e controllo sono protette','Content filtering interno','I flussi di comunicazione tra domini di sicurezza differenti devono essere analizzati da un meccanismo di content filtering al fine di prevenire esfiltrazione di dati riservati.','','','SHOULD','RIF-103','','si','','',''),
  ('SEC-PT5-001.00','1','Protective Technology (PR.PT)','PR.PT-5: Sono implementati meccanismi (es. failsafe, load balancing, hot swap) che permettono di soddisfare requisiti di resilienza sia durante il normale esercizio che in situazioni avverse','Strategie  di continuità operativa','Deve essere implementata e documentata la strategia di continuità operativa necessaria per rispondere ai requisiti di continuità di servizio.\\\\\\\\n\\\\\\\\nEsempi di possibili elementi della strategia:\\\\\\\\n\\\\\\\\n - implementazione di meccanismi di alta affidabilità per garantire la continuità a fronte di un fault di servizio\\\\\\\\n - predisposizione di una infrastruttura ridondata su un sito alternativo, in modalità active-active o active-passive, per garantire continuità a fronte di un fault di sito\\\\\\\\n - predisposizione di una infrastruttura ridondata o una tipologia di backup su un sito alternativo distante almeno 25 km, per garantire continuità a fronte di un fault metropolitano','','','MUST','RIF-101
LGA','','si','','','si'),
  ('SEC-PT5-002.00','1','Protective Technology (PR.PT)','PR.PT-5: Sono implementati meccanismi (es. failsafe, load balancing, hot swap) che permettono di soddisfare requisiti di resilienza sia durante il normale esercizio che in situazioni avverse','BCDR - Ridondanza','L''''infrastruttura del servizio deve garantire un adeguato livello di ridondanza delle componenti critiche per l''''erogazione del servizio stesso, come ad esempio:\\\\\\\\n - sistemi di storage ridondati\\\\\\\\n - linee di alimentazione duplicate\\\\\\\\n - connessioni di rete multiple\\\\\\\\n - utilizzo di sistemi in cluster','','','MUST','RIF-101','','si','','',''),
  ('SEC-PT5-003.00','1','Protective Technology (PR.PT)','PR.PT-5: Sono implementati meccanismi (es. failsafe, load balancing, hot swap) che permettono di soddisfare requisiti di resilienza sia durante il normale esercizio che in situazioni avverse','BCDR - Resilienza','Devono essere adottati dei meccanismi automatici di identificazione dei problemi nella erogazione del servizio che garantiscano continuità nella erogazione del servizio o l''''attivazione di soluzioni di continuità operativa.','','','MUST','RIF-101
LGA','','si','','','si'),
  ('SEC-AE2-001.00','1','Anomalies and Events (DE.AE)','DE.AE-2: Gli eventi rilevati vengono analizzati per comprendere gli obiettivi e le metodologie dell''''attacco','Threat hunting','I log di sicurezza devono essere analizzati per identificare nuove modalità di attacco e nuovi TTP e per predisporre nuove tipologie di allarmi.','','','MUST','','','','','',''),
  ('SEC-CM1-001.00','2','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Generazione dei log','Tutti gli eventi rilevanti per l''''erogazione del servizio o per l''''integrità di sistemi e applicazioni devono generare dei log di sicurezza.','','','MUST','LGA
Change','','','si','','si'),
  ('SEC-CM1-001.01','3','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Security log prodotti dalle applicazioni','Eventi generati dagli utenti, sia riusciti che falliti, al minimo:\\\\\\\\n\\\\\\\\nTutte le interazioni con i meccanismi di autenticazione:\\\\\\\\n\\\\\\\\n - autenticazione \\\\\\\\n - cambio password\\\\\\\\n - reset password\\\\\\\\n - recupero username\\\\\\\\n - modifica della modalità di autenticazione (e.g. abilitazione/disabilitazione 2FA)\\\\\\\\n - modifica alle anagrafiche (incluso canali di contatto, gestione dispositivo utente)\\\\\\\\n - delega di privilegio di accesso ad altri utenti\\\\\\\\n - registrazione utente\\\\\\\\n\\\\\\\\nTutte le interazioni con le funzionalità principali offerte dal servizio; a titolo esemplificativo e non esaustivo:\\\\\\\\n\\\\\\\\n - Invio e consultazione di email\\\\\\\\n - Invio e consultazione di fatture elettroniche\\\\\\\\n - per i servizi trust (es: Firma, Conservazione, CSB, Certified Platform):\\\\\\\\n   + upload e scarico di documenti\\\\\\\\n   + Firma di documenti\\\\\\\\n - avvio e arresto di Macchine Virtuali, container o altre risorse dei servizi Cloud\\\\\\\\n\\\\\\\\nTutte le cancellazioni o modifiche alle configurazioni rilevanti dei servizi, modificabili dall''''utente; a titolo esemplificativo e non esaustivo:\\\\\\\\n\\\\\\\\n - Per i servizi DNS (in aggiunta ai precedenti):\\\\\\\\n    + inserimento di entry DNS Domini\\\\\\\\n    + per la modifica, cancellazione o inserimento di record DNS\\\\\\\\n - Per i servizi di Posta (PEC / PEL):\\\\\\\\n    + Creazione, modifica e cancellazione di regole di inoltro\\\\\\\\n    + Creazione, modifica e cancellazione di display name\\\\\\\\n    + Creazione casella di posta\\\\\\\\n - Per i servizi di firma e conservazione (es. Certified Platform, Firma, CSB)\\\\\\\\n    + Creazione modifica e cancellazione di workflow\\\\\\\\n    + Creazione modifica e cancellazione delle azioni connesse ai workflow \\\\\\\\n - Per i servizi Cloud\\\\\\\\n    + Creazione modifica cancellazione delle risorse disponibili nella piattaforma (es. Host, storage, reti virtuali, fw..)\\\\\\\\n---- \\\\\\\\n\\\\\\\\nEventi, sia riusciti che falliti, generati a seguito di attività amministrative (ossia per tutte le modifiche rilevanti che determinano variazioni nella fruizione del servizio o nel funzionamento del sistema) e/o di assistenza clienti, al minimo:\\\\\\\\n\\\\\\\\n - gli eventi di autenticazione riportati all''''inizio\\\\\\\\n - creazione, modifica o cancellazione di account\\\\\\\\n - creazione, modifica o cancellazione di gruppi e di appartenenza a gruppi\\\\\\\\n - concessione, modifica o rimozione di autorizzazioni ad account e gruppi\\\\\\\\n - la modifica della modalità di autenticazione (e.g. abilitazione/disabilitazione 2FA)\\\\\\\\n - cancellazione o modifica alle configurazioni \\\\\\\\n - uso dei privilegi (es. azioni utente svolte dall''''assistenza clienti)\\\\\\\\n - l''''attivazione o disattivazione del meccanismo di logging (se la configurazione è modificabile a runtime)\\\\\\\\n - il cambio del livello di dettaglio del logging (se la configurazione è modificabile a runtime)\\\\\\\\n - cancellazione o modifica alle anagrafiche (incluso canali di contatto, gestione dispositivo utente)\\\\\\\\n - eventi di lettura o scarico di dati o file contenenti informazioni gestite dalle applicazioni, sistemi o elementi di middleware (e.g. database)','','Gli eventi generati a seguito di attività amministrative includono i log degli AdS (Amministratori di Sistema)','MUST','LGA
Change','','','si','','si'),
  ('SEC-CM1-001.02','2','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Security log prodotti dai sistemi (Server, Apparati di rete e MW)','Tutte le interazioni con i meccanismi di autenticazione, includendo eventi (riusciti e falliti):\\\\\\\\n\\\\\\\\n - autenticazione \\\\\\\\n - cambio password\\\\\\\\n - reset password\\\\\\\\n - modifica privilegi (es. modifica sudoers file)\\\\\\\\n\\\\\\\\nEventi generati a seguito di attività amministrative (ossia per tutte le modifiche rilevanti che determinano variazioni nella fruizione del servizio o nel funzionamento del sistema) al minimo:\\\\\\\\n\\\\\\\\n - creazione, modifica o cancellazione di account\\\\\\\\n - creazione, modifica o cancellazione di gruppi e di appartenenza a gruppi\\\\\\\\n - concessione, modifica o rimozione di autorizzazioni ad account e gruppi\\\\\\\\n - la modifica della modalità di autenticazione (e.g. abilitazione/disabilitazione 2FA)\\\\\\\\n - uso dei privilegi (es: sudo)\\\\\\\\n - avvio e arresto di processi e device\\\\\\\\n - avvio, arresto e cancellazione di servizi\\\\\\\\n - l''''attivazione o disattivazione del meccanismo di logging\\\\\\\\n - il cambio del livello di dettaglio del logging\\\\\\\\n - attivazione e disattivazione di sistemi di protezione (es: firewall, antivirus, etc.)\\\\\\\\n - cancellazione o modifica alle configurazioni ','','Gli eventi generati a seguito di attività amministrative includono i log degli AdS (Amministratori di Sistema)','MUST','RIF-107
Change','','si','si','',''),
  ('SEC-CM1-001.03','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Log dell''''accesso ai dati','Gli eventi di lettura o scarico di dati o file contenenti informazioni gestite dalle applicazioni, sistemi o elementi di middleware (e.g. database) devono generare log di sicurezza.','','','MUST','LGA','','','','','si'),
  ('SEC-CM1-001.04','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Altre tipologie di log','Devono essere prodotti log di sicurezza per controllare i seguenti eventi:\\\\\\\\n - traffico telematico prodotto da sistemi e applicazioni\\\\\\\\n - occupazione della risorse di sistema','','','MUST','','','','','',''),
  ('SEC-CM1-001.05','2','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Security log prodotti dalle soluzioni di sicurezza','A livello minimo, include:\\\\\\\\n\\\\\\\\n - DNS (autoritativi), tutte le richieste \\\\\\\\n - Firewall, esito delle rules relative a traffico che traversa il perimetro e gli ambienti di produzione, configurazioni logiche (creazione, modifica e cancellazione ACL), creazione, modifica e cancellazione VLAN\\\\\\\\n - VPN, esito richieste di connessione\\\\\\\\n - IDS, allarmi\\\\\\\\n - DNS protection system, richieste ed allarmi\\\\\\\\n - Antivirus ed EDR, allarmi\\\\\\\\n - HSM, apertura dello chassis, funzioni di key management\\\\\\\\n - WAF, allarmi, creazione, modifica e cancellazione delle security policy\\\\\\\\n - Network device, netflow, configurazioni logiche (creazione, modifica e cancellazione ACL), creazione, modifica e cancellazione VLAN\\\\\\\\n - Backup, eventi relativi alla pianificazione dei salvataggi, eventi relativi all''''uso delle crittografia (es. rotazione chiavi, uso della cifratura)\\\\\\\\n - Storage, eventi relativi all''''uso delle crittografia (es. rotazione chiavi, uso della cifratura), allarmi anti-ransomware (se disponibile la funzionalità)','','','MUST','','','','','',''),
  ('SEC-CM1-002.00','4','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Centralizzazione e conservazione dei Security log','Tutti i log relativi agli eventi descritti nei requisiti precedenti devono essere:\\\\\\\\n - conferiti al sistema di raccolta in tempo reale, ove possibile, o con un ritardo massimo di 5 minuti\\\\\\\\n - raccolti anche dall''''infrastruttura centralizzata di log management\\\\\\\\n - conservati per il periodo di retention definito in SEC-CM1-002.02  e cancellati al termine di tale periodo\\\\\\\\n - protetti da manipolazione o cancellazione\\\\\\\\nI requisiti di protezione e conservazione si applicano a tutte le copie centralizzate dei log (es. backup).','','Rif. 14 - STANDARD - Log Management - Data Center - Confluence (intranet.example)\\\\\\\\nContattare Juan Mascarello per dettagli','MUST','LGA','','','','','si'),
  ('SEC-CM1-002.01','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Conferimento dei dati per Security monitoring,  detection e Incident management','I security log citati nei precedenti requisiti devono essere resi disponibili in near real time e entro 5 minuti al team di Sicurezza mediante gli strumenti in loro uso (SIAR) per analisi e correlazione finalizzata alla detection e all''''Incident management.','','','MUST','','','','','',''),
  ('SEC-CM1-002.02','2','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Conservazione dei log e delle correlazioni','Tutti i log devono essere conservati per almeno 6 mesi.\\\\\\\\n\\\\\\\\nI log dei sistemi più critici (es. per il rilascio di prodotti trust o nell''''ambito del riconoscimento dei clienti) devono essere conservati per almeno 12 mesi.\\\\\\\\n\\\\\\\\nIn alcuni casi, come ad esempio:\\\\\\\\n\\\\\\\\n - sistemi afferenti a servizi sottoposti a qualifica ACN\\\\\\\\n - sistemi afferenti a servizi inclusi nel Perimetro Nazionale di Sicurezza Cibernetica\\\\\\\\n\\\\\\\\nè necessario conservare i log per un periodo di tempo definito da normativa specifica (es. 24 mesi).\\\\\\\\n\\\\\\\\n Le attività di analisi e correlazione svolte dal team di sicurezza sui log e su altre fonti (IoC condivisi dal CSIRT ACN) producono allarmi che devono essere conservati almeno per il medesimo periodo di retention dei log.','','','MUST','','','','','',''),
  ('SEC-CM1-002.03','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Protezione dell''''integrità dei log','Non deve essere possibile agli utilizzatori dei sistemi di log management alterare o cancellare i log.\\\\\\\\n\\\\\\\\nGli amministratori di sistema dei sistemi di log management devono avere segregazione di ruolo rispetto agli amministratori dei sistemi che producono i log.','','','MUST','','','','','',''),
  ('SEC-CM1-002.04','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Compliance','Deve essere garantita la conservazione integra del log originale (raw log)\\\\\\\\n\\\\\\\\nNel caso di log modificati in maniera automatica dai sistemi, questi devono contenere anche il raw dell''''originale.','','','MUST','','','','','',''),
  ('SEC-CM1-003.00','3','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Struttura dei Security log','Tutti i log devono contenere almeno le seguenti informazioni:\\\\\\\\n - timestamp\\\\\\\\n - nome dell''''evento\\\\\\\\n - descrizione dell''''evento\\\\\\\\n - identificativo dell''''utenza\\\\\\\\n - identificativo della componente acceduta che ha generato il log (indirizzo IP e modulo applicativo)\\\\\\\\n - provenienza dell''''operazione (indirizzo IP e strumento utilizzato dall''''utente)\\\\\\\\n - livello di autorizzazione dell''''utente\\\\\\\\n - esito dell''''operazione\\\\\\\\n - livello di severity (se applicabile)\\\\\\\\n - azione / conseguenza (e.g. blocco account, notifica, etc.)','','','MUST','LGA','','','','','si'),
  ('SEC-CM1-004.00','2','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Sincronizzazione clock','Per garantire la coerenza temporale dei log prodotti, i clock dei sistemi devono essere sincronizzati con gli appositi riferimenti temporali interni, tramite protocollo NTP; i sistemi di riferimento interni devono a loro volta essere sincronizzati con riferimenti certi di informazioni temporali affidabili.','','','MUST','Change','','','si','',''),
  ('SEC-CM1-005.00','3','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Dati da non riportare nei log','Le seguenti informazioni non devono mai essere presenti nei log:\\\\\\\\n - credenziali di autenticazione (e.g. password, token, OTP, etc.)\\\\\\\\n - chiavi crittografiche (e.g. private, simmetriche, etc.)\\\\\\\\n - dati relativi a strumenti di pagamento (e.g. PAN di carte di credito, CVV, IBAN)\\\\\\\\n - dati personali non necessari alla funzione del log \\\\\\\\n - dati personali che rivelino l''''origine razziale o etnica, le opinioni politiche, le convinzioni religiose o filosofiche, o l''''appartenenza sindacale, nonché dati genetici, dati biometrici intesi a identificare in modo univoco una persona fisica, dati relativi alla salute o alla vita sessuale o all''''orientamento sessuale della persona;\\\\\\\\n - dati personali relativi a condanne penali e reati\\\\\\\\nLaddove sia necessario registrare informazioni strettamente riservate, queste devono essere anonimizzate o mascherate in modo opportuno.\\\\\\\\n','','','MUST','LGA','','','','','si'),
  ('SEC-CM1-006.00','2','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Aggiornamento use case di allarme','In sede di progetto deve essere identificata la necessità di creare nuove casistiche di allarme (use case) specifiche per quanto si sta realizzando, includendo:\\\\\\\\n - modalità di reazione (playbook)\\\\\\\\n - allarmi necessari e logica di identificazione (detection)\\\\\\\\n - log source necessari per la creazione degli allarmi\\\\\\\\n - mappatura delle sequenze di attacco su possibili tecniche e tattiche note riconducibili a soggetti malevoli noti (threat actor), utilizzando come riferimento il Mitre ATT&CK','','Ad esempio, in caso di visualizzazioni superiori ad una soglia definita in base al caso di specie (es. >100 al giorno nel caso in cui la media dell''''operatore sia 80) devono essere prodotti degli alert verso:\\\\\\\\nil responsabile dell''''operatore in caso di operatori interni;\\\\\\\\nil responsabile/referente interno in caso i operatori esterni (es. Partner/CDRL)','MUST','LGA','','','','','si'),
  ('SEC-CM1-007.00','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Gestione allarmi','L''''analisi degli allarmi deve avvenire immediatamente per gli allarmi ad alta priorità. \\\\\\\\nAltre casistiche di priorità inferiore devono essere analizzate periodicamente.','','','MUST','','','','','',''),
  ('SEC-CM1-009.00','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','BCDR - Monitoraggio','Devono essere adottati sistemi di monitoraggio per identificare rapidamente eventuali eventi che possano comportare una interruzione di servizio e così attivare le relative procedure di ripristino e risposta.','','','MUST','LGA','','','','','si'),
  ('SEC-CM1-010.00','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Identificazione di anomalie nei backup','I sistemi di backup devono essere in grado di identificare significativi scostamenti della quantità di dati regolarmente sottoposti a backup ed eventualmente attivare appositi sistemi di allarme.','','','SHOULD','','','','','',''),
  ('SEC-CM1-011.00','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Disponibilità dei Security log','Deve essere garantita la disponibilità alla ricerca e consultazione dei log con le seguenti prestazioni:\\\\\\\\n\\\\\\\\n - 5 minuti come tempo massimo per interrogazioni relative a log originati negli ultimi 7 gg\\\\\\\\n - 15 minuti come tempo massimo per interrogazioni relative a log originati negli ultimi 90 gg \\\\\\\\n - 4h come tempo massimo per interrogazioni relative a log originati oltre i 90 gg','','','MUST','','','','','',''),
  ('SEC-CM1-011.01','1','Security Continuous Monitoring (DE.CM)','DE.CM-1: Viene svolto il monitoraggio della rete informatica per rilevare potenziali eventi di cybersecurity','Parametri di DR per i Security log','Devono essere garantiti i seguenti parametri per l''''infrastruttura di gestione dei security log:\\\\\\\\n\\\\\\\\nRTO=4h\\\\\\\\n\\\\\\\\nRPO=0','','','MUST','','','','','',''),
  ('SEC-CM4-001.00','1','Security Continuous Monitoring (DE.CM)','DE.CM-4: Il codice malevolo viene rilevato','Rilevazione codice malevolo','Tutti i file in ingresso sui sistemi Azienda devono essere sottoposti ad analisi antimalware al fine di rilevare la presenza di eventuale codice malevolo.','','AntivirusAsAService - intranet.example','MUST','LGA','','','','','si'),
  ('SEC-DP4-001.00','1','Detection Processes (DE.DP)','DE.DP-4: L''''informazione relativa agli eventi rilevati viene comunicata','Analisi automatica','I log di sicurezza devono essere arricchiti ("enriched"), prioritizzati, correlati e allarmati in tempo reale. Periodicamente devono essere prodotti report di analisi e KPI per identificare trend di eventi che si sono realizzati. In particolare deve essere prevista l''''analisi periodica:\\\\\\\\n - dell''''attività degli amministratori di sistema\\\\\\\\n - dell''''andamento delle fonti di attacco\\\\\\\\n','','','MUST','','','','','',''),
  ('SEC-CO1-001.00','1','Communications (RS.CO)','RS.CO-1: Il personale conosce il proprio ruolo e le operazioni che deve svolgere in caso sia necessaria una risposta ad un incidente','BCDR - Formazione del personale','Il personale avente un ruolo operativo nella attività di gestione delle emergenze del servizio deve essere formato:\\\\\\\\n - sulle specifiche procedure e modalità di ripristino del servizio medesimo\\\\\\\\n - sui ruoli e sulle responsabilità in caso di emergenza\\\\\\\\n - sui punti di contatto per le comunicazioni inerenti al servizio.','','','MUST','LGA','','','','','si');
